local config = {
  ui_story_5079_50790100_1_dialog_content = "<color=#e8d9bb>Clic-clic, clic-clic—</color>",
  ui_story_5079_50790100_2_dialog_content = "Pact?",
  ui_story_5079_50790100_3_dialog_content = "<color=#e8d9bb>Clic-clic, clic-clic—</color>",
  ui_story_5079_50790100_4_dialog_content = "... Hum?",
  ui_story_5079_50790100_5_dialog_content = "\"Hmm\"? Em um momento como este, é realmente tudo o que você tem a dizer? Por favor, explique-se agora mesmo.",
  ui_story_5079_50790100_6_dialog_content = "Ah...",
  ui_story_5079_50790100_7_dialog_content = "Não entenda mal - não estou aqui para roubar sua Mala Branca. Eu só vim retirar algum dinheiro que deixei lá dentro.",
  ui_story_5079_50790100_8_dialog_content = "... Quantas vezes eu já te disse para não colocar coisas dentro da minha Mala Branca? Você tem ideia de como é difícil fazer ela cuspir tudo de volta?",
  ui_story_5079_50790100_9_dialog_content = "Se você veio extorquir dinheiro de mim, o mínimo que você pode fazer é pensar em uma desculpa melhor.",
  ui_story_5079_50790100_10_dialog_content = "\"Extorquir\"? Eu nunca faria algo tão impróprio! Eu só não conseguia pensar em um lugar mais seguro para guardar meu dinheiro, só isso...",
  ui_story_5079_50790100_11_dialog_content = "Pergunte à sua Mala Branca se não acredita em mim! Você pode se comunicar com ela, certo?",
  ui_story_5079_50790100_12_dialog_content = "... Esqueça. Agora não é o melhor momento para você fazer um \"saque\" da Mala Branca.",
  ui_story_5079_50790100_13_dialog_content = "Aqui, isso é suficiente para você?",
  ui_story_5079_50790100_14_dialog_content = "Você está tentando me insultar? O que é essa ninharia?",
  ui_story_5079_50790100_15_dialog_content = "Então, que tal isso? Ainda acha que é uma ninharia?",
  ui_story_5079_50790100_16_dialog_content = "Ainda não é o suficiente.",
  ui_story_5079_50790100_17_dialog_content = "Então aqui, mas isso é o último. Qualquer coisa a mais e eu começarei a suspeitar de suas intenções.",
  ui_story_5079_50790100_18_dialog_content = "Podemos parar de rodeios já? Apenas me dê todo o dinheiro que você está carregando agora, e podemos terminar aqui.",
  ui_story_5079_50790100_19_dialog_content = "Tudo isso? Você finalmente foi cegado pelo mal e, portanto, precisa de uma quantia exorbitante de dinheiro para realizar seus atos perversos?",
  ui_story_5079_50790100_20_dialog_content = "Do que você está falando? Eu só preciso de dinheiro para comprar ingredientes para o nosso <color=#FFB400>banquete</color>!",
  ui_story_5079_50790100_21_dialog_content = "Raramente tenho a chance de assumir a responsabilidade por algo assim. É a oportunidade perfeita...",
  ui_story_5079_50790100_22_dialog_content = "Posso mostrar a todos vocês o que significa executar uma missão de maneira impecável. Assim, as pessoas vão parar de me tratar como um personagem secundário.",
  ui_story_5079_50790100_23_dialog_content = "Você está adquirindo ingredientes para o nosso <color=#FFB400>banquete</color>? E acha que pode realizar uma tarefa tão importante com suas economias insignificantes?",
  ui_story_5079_50790100_24_dialog_content = "Humph! Confie em mim, eu tenho alguns truques na manga. Agora entregue todo o seu dinheiro!",
  ui_story_5079_50790100_25_dialog_content = "Muito bem, mas se eu falhar em recuperar a mesma quantidade de dentro da minha Mala Branca, eu vou—",
  ui_story_5079_50790100_26_dialog_content = "Sim, sim, eu sei!",
  ui_story_5079_50790100_27_dialog_content = "Heheheh, apenas espere! Este próximo banquete vai derrubar as meias de todos!",
  ui_story_5079_50790100_28_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790100_29_dialog_content = "Urgh... Minha cabeça...",
  ui_story_5079_50790100_30_dialog_content = "Eu cochilei sem querer? Meu sonho pareceu tão longo também... Mas sobre o que era?",
  ui_story_5079_50790100_31_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790100_32_dialog_content = "Espera... Estou em um trem?",
  ui_story_5079_50790100_33_dialog_content = "Raios! Acho que não tenho tempo suficiente para comprar roupas novas—",
  ui_story_5079_50790100_34_dialog_content = "Huh? Espere, minhas roupas...",
  ui_story_5079_50790100_35_dialog_content = "Heh, acho que eu não estava completamente acordado agora há pouco. Parece que eu já mudei de roupa.",
  ui_story_5079_50790100_36_dialog_content = "Antes de conduzir qualquer tipo de negócio, fazer com que você pareça digno e apresentável é a coisa mais importante que você pode fazer.",
  ui_story_5079_50790100_37_dialog_content = "Apenas fazendo isso os clientes ricos lhe darão seu tempo e seu patrocínio.",
  ui_story_5079_50790100_38_dialog_content = "Foi o que ele disse... todos aqueles anos atrás.",
  ui_story_5079_50790100_39_dialog_content = "Mesmo que eu mal consiga lembrar como ele se parece, suas reclamações ainda ecoam na minha cabeça...",
  ui_story_5079_50790100_40_dialog_content = "De qualquer forma, não consigo deixar de confiar nele quando se trata de fazer negócios.",
  ui_story_5079_50790100_41_dialog_content = "Afinal, ele poderia ter se tornado um poderoso comerciante naquela época se não fosse por mim... Heh.",
  ui_story_5079_50790100_42_dialog_content = "<color=#e8d9bb>O trem está chegando agora em <color=#FFB400>Folta Town</color>.</color>",
  ui_story_5079_50790100_43_dialog_content = "Folta... uma cidade famosa por seus mercados de alimentos por atacado. Finalmente estou quase lá, hein?",
  ui_story_5079_50790100_44_dialog_content = "Aposto que esses preguiçosos nunca se deram ao trabalho de vir até aqui atrás de ingredientes!",
  ui_story_5079_50790100_45_dialog_content = "Ainda assim, devo agradecer a eles por colocarem a fasquia tão baixa. Isso apenas significa que vou ofuscá-los ainda mais quando terminar isso.",
  ui_story_5079_50790100_46_dialog_content = "Eu até posso realizar meu desejo se fizer isso direito, e não terei que trabalhar mais para aquela coisa...",
  ui_story_5079_50790100_47_dialog_content = "Você se saiu bem, Pact. Como recompensa, concederei um desejo seu.",
  ui_story_5079_50790100_48_dialog_content = "Se eu me lembro corretamente, seu desejo original... era se livrar da Pedra de Caça, certo?",
  ui_story_5079_50790100_49_dialog_content = "Quando você tiver tomado sua decisão, venha me encontrar.",
  ui_story_5079_50790100_50_dialog_content = "Minha nossa, Pact! Estou impressionado que você conseguiu reunir ingredientes tão primorosos para o nosso banquete.",
  ui_story_5079_50790100_51_dialog_content = "Na verdade... Eu nunca conseguiria realizar tal façanha para mim mesmo.",
  ui_story_5079_50790100_52_dialog_content = "Por favor, você precisa me ensinar seus métodos.",
  ui_story_5079_50790100_53_dialog_content = "Heheh... Heheheheh...",
  ui_story_5079_50790100_54_dialog_content = "Desculpe-me, senhorita, mas parece que você esqueceu sua bagagem.",
  ui_story_5079_50790100_55_dialog_content = "Hã? Acho que está me confundindo com outro passageiro. Não sou do tipo de pessoa que perde seus pertences.",
  ui_story_5079_50790100_56_dialog_content = "Desculpe, é só que a bagagem combina muito com a sua roupa, então eu presumi que pertencia a você.",
  ui_story_5079_50790100_57_dialog_content = "...",
  ui_story_5079_50790100_58_dialog_content = "Ah, você quer dizer a Pedra de Caça? Não se preocupe, ela me segue por onde eu vou. Não consigo me livrar dela mesmo que eu queira.",
  ui_story_5079_50790100_59_dialog_content = "Estou surpreso que você não tenha se assustado com isso. Isso é bastante raro.",
  ui_story_5079_50790100_60_dialog_content = "Assustado? Claro que não! Na verdade, acho bastante encantador.",
  ui_story_5079_50790100_61_dialog_content = "(Parece que este maestro é bastante de mente aberta. Não consigo contar quantas vezes as pessoas me evitaram por causa da Pedra de Caça.)",
  ui_story_5079_50790100_62_dialog_content = "(Mesmo aquelas lojas de roupas que afirmam \"cliente em primeiro lugar\" não me dariam a hora do dia...)",
  ui_story_5079_50790100_63_dialog_content = "C-Com licença, mas... o-o que raios é aquela coisa atrás de você?",
  ui_story_5079_50790100_64_dialog_content = "Talvez seja melhor se você tentar outra loja, senhorita. Embora você certamente possa pagar por nossas roupas, temo que não possamos nos dar ao luxo de perder clientes por causa do seu... companheiro.",
  ui_story_5079_50790100_65_dialog_content = "Não há necessidade de oferecer mais dinheiro, senhorita...",
  ui_story_5079_50790100_66_dialog_content = "Posso fazer uma sugestão? Se não se importar, por que não comprar algo para fazer seu amigo parecer... um pouco menos intimidador?",
  ui_story_5079_50790100_67_dialog_content = "Caso contrário, temo que estrague a aparência do seu traje, e seu dinheiro será mal gasto...",
  ui_story_5079_50790100_68_dialog_content = "Você diz que se chama Pedra de Caça? Que nome magnífico! Meu trem, Outro Fim, também tem um nome igualmente impressionante.",
  ui_story_5079_50790100_69_dialog_content = "Não me lembro de ter pedido o nome do seu trem...",
  ui_story_5079_50790100_70_dialog_content = "Posso ver que sua Pedra de Caça é muito parecida com o meu Outro Fim, pois ocupam lugares semelhantes em nossos corações.",
  ui_story_5079_50790100_71_dialog_content = "Então você pode ter que verificar seus olhos, a menos que queira abandonar este trem também. Para mim, Hunting Stone... não é nada além de um incômodo.",
  ui_story_5079_50790100_72_dialog_content = "Hahaha! Eu nunca abandonaria meu velho amigo, e algo me diz... nem você. Até a próxima vez que nos encontrarmos, minha senhora.",
  ui_story_5079_50790100_73_dialog_content = "Do que diabos ele estava falando?",
  ui_story_5079_50790100_74_dialog_content = "Escute, Pedra de Caça. Eu sei que você não entende quanto dinheiro eu gastei nessas decorações para você...",
  ui_story_5079_50790100_75_dialog_content = "Mas você tem que prometer não assustar ninguém. Esta missão significa tudo para mim!",
  ui_story_5079_50790100_76_dialog_content = "!",
  ui_story_5079_50790100_77_dialog_content = "Bom! Já que estamos na mesma página agora, você pode parar de se mover mais rápido do que eu—",
  ui_story_5079_50790100_78_dialog_content = "O-O que é essa coisa?",
  ui_story_5079_50790100_79_dialog_content = "...Ótimo. Ainda nem saímos do trem e já estamos assustando as pessoas.",
  ui_story_5079_50790100_80_dialog_content = "Algo tão elegante deve pertencer a uma pessoa bastante importante...",
  ui_story_5079_50790100_81_dialog_content = "Ahem... Desculpe por isso. Vou tirar isso daqui agora.",
  ui_story_5079_50790100_82_dialog_content = "Você? Me diga, você é um dos ricos elites de Lumópolis, ou talvez Umbraton?",
  ui_story_5079_50790100_83_dialog_content = "Por favor, desculpe a minha grosseria agora mesmo! Eu não quis dizer nada com isso...",
  ui_story_5079_50790100_84_dialog_content = "Por que você está se desculpando? Sou eu que estou no seu caminho, não é?",
  ui_story_5079_50790100_85_dialog_content = "Sinto-me honrado por ter compartilhado este trem com você hoje, minha senhora. Boa viagem...",
  ui_story_5079_50790100_86_dialog_content = "Th-Obrigado.",
  ui_story_5079_50790100_87_dialog_content = "Tão estranho... O que houve com aquele cara agora mesmo? Essas roupas são mágicas ou algo assim?",
  ui_story_5079_50790100_88_dialog_content = "E por que sinto que já o vi em algum lugar antes?",
  ui_story_5079_50790100_89_dialog_content = "Ah, esquece. Agora não é hora de se preocupar com essas coisas...",
  ui_story_5079_50790100_90_dialog_content = "*cheira*",
  ui_story_5079_50790100_91_dialog_content = "Uau, esses cheiros... Carne e tomates! Biscoitos de creme e pão recém-assado! E mais...",
  ui_story_5079_50790100_92_dialog_content = "Isso é tão Folta! Nós nem mesmo saímos do trem, e eu já consigo sentir o cheiro de tanta comida maravilhosa!",
  ui_story_5079_50790100_93_dialog_content = "Parece que teremos que experimentar alguns pratos locais antes de começar os negócios!",
  ui_story_5079_50790100_94_dialog_content = "!",
  ui_story_5079_50790200_1_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5079_50790200_2_dialog_content = "Então, isso é Folta!",
  ui_story_5079_50790200_3_dialog_content = "A arquitetura é tão única. Este lugar parece ser muito mais obcecado por comida do que Umbraton!",
  ui_story_5079_50790200_4_dialog_content = "Hã? Será que essas casas são feitas de ingredientes reais?",
  ui_story_5079_50790200_5_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790200_6_dialog_content = "Ah... Vou perder o trem! Com licença!",
  ui_story_5079_50790200_7_dialog_content = "Hã?",
  ui_story_5079_50790200_8_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5079_50790200_9_dialog_content = "Ai...",
  ui_story_5079_50790200_10_dialog_content = "Acabei de comprar essas roupas também! Aposto que estão imundas agora!",
  ui_story_5079_50790200_11_dialog_content = "Hã? Eles não estão sujos de todo. Na verdade, eles estão exalando um aroma doce... Espere, essas pedras no chão são feitas de doce?",
  ui_story_5079_50790200_12_dialog_content = "...",
  ui_story_5079_50790200_13_dialog_content = "Eu me pergunto qual é o gosto deles? Eu geralmente como pedras de Lumópolis para ajudar na digestão, então uma pequena mordida não deve machucar...",
  ui_story_5079_50790200_14_dialog_content = "Ah!",
  ui_story_5079_50790200_15_dialog_content = "Uhh?",
  ui_story_5079_50790200_16_dialog_content = "O que você pensa que está fazendo, senhorita? Essas pedras não são para comer!",
  ui_story_5079_50790200_17_dialog_content = "Heh, diga você... Além disso, quem é você para me dizer que eu não posso comê-los?",
  ui_story_5079_50790200_18_dialog_content = "Você parece não entender, o que provavelmente significa que você não é daqui.",
  ui_story_5079_50790200_19_dialog_content = "Essas pedras são alimento para os <color=#FFB400>pardais de doce</color>. É por causa da ajuda deles que podemos construir nossos prédios com comida!",
  ui_story_5079_50790200_20_dialog_content = "Como você poderia pensar em privar essas criaturas tão trabalhadoras de sua comida?",
  ui_story_5079_50790200_21_dialog_content = "Então você está dizendo que todos os prédios aqui são realmente feitos de comida?",
  ui_story_5079_50790200_22_dialog_content = "Uh-huh! Apenas dê uma olhada ao redor - as tábuas do chão são feitas de grãos de cacau, e os postes de rua são pirulitos brilhantes, e...",
  ui_story_5079_50790200_23_dialog_content = "Ei! O que você está fazendo com aquela lâmpada de rua?",
  ui_story_5079_50790200_24_dialog_content = "A penalidade por danificar a propriedade pública é séria! Eles vão te pendurar na rua e deixar pardais de doces te bicarem até virar pedaços...",
  ui_story_5079_50790200_25_dialog_content = "Você não sabe nada sobre este lugar?",
  ui_story_5079_50790200_26_dialog_content = "Soa como um monte de baboseira para mim. Tem certeza de que não está apenas inventando tudo isso?",
  ui_story_5079_50790200_27_dialog_content = "Está brincando? Essa é a principal razão pela qual as ruas de Folta são tão limpas e arrumadas!",
  ui_story_5079_50790200_28_dialog_content = "Sabe, senhorita... Mesmo que você esteja vestindo roupas tão sofisticadas, você está agindo sem diferença de uma criança.",
  ui_story_5079_50790200_29_dialog_content = "Acho que meu pai estava mentindo quando disse que pessoas bem vestidas se comportam melhor que as outras!",
  ui_story_5079_50790200_30_dialog_content = "Diga... Você não roubou essa roupa, roubou? Roubou?",
  ui_story_5079_50790200_31_dialog_content = "Hã? Quero que saiba que gastei uma fortuna nessas roupas...",
  ui_story_5079_50790200_32_dialog_content = "(Hunf, eu não tenho que ficar aqui e aguentar isso de uma garotinha.)",
  ui_story_5079_50790200_33_dialog_content = "(Ela não tem respeito pelos mais velhos, ou limites, aliás... Mas por algum motivo, sua atitude irritante é estranhamente familiar.)",
  ui_story_5079_50790200_34_dialog_content = "Hum... Sinto que esbarrar nesta senhora estranha me fez esquecer algo...",
  ui_story_5079_50790200_35_dialog_content = "<color=#e8d9bb>Choooooo—</color>",
  ui_story_5079_50790200_36_dialog_content = "Ah droga, o trem! Ele partiu!",
  ui_story_5079_50790200_37_dialog_content = "Isso é tudo culpa sua! Primeiro você esbarrou em mim, depois desperdiçou todo o meu tempo com suas palhaçadas, e finalmente eu perdi o trem!",
  ui_story_5079_50790200_38_dialog_content = "Meu plano de fugir de casa está arruinado! Espero que você esteja pronto para me compensar!",
  ui_story_5079_50790200_39_dialog_content = "Hã? Você estava fugindo? E o que você quer dizer com \"compensar para mim\"?",
  ui_story_5079_50790200_40_dialog_content = "Você é quem esbarrou em mim... Se for o caso, você deveria estar me compensando!",
  ui_story_5079_50790200_41_dialog_content = "Além disso, acabei de te fazer um grande favor ao frustrar seu pequeno plano de fugir. Alguma gratidão seria bom, não acha?",
  ui_story_5079_50790200_42_dialog_content = "Hã? Você está sonhando se acha que eu deveria estar te agradecendo! Além disso, você teria sido picado até virar pedaços se não fosse por mim!",
  ui_story_5079_50790200_43_dialog_content = "Se alguém deveria estar grato aqui, é você!",
  ui_story_5079_50790200_44_dialog_content = "Não entenda mal, criança! Eu só fiz isso porque estava pesquisando ingredientes!",
  ui_story_5079_50790200_45_dialog_content = "Você não pensou que eu ia comer pedras só porque estava com fome, pensou? Pensou?",
  ui_story_5079_50790200_46_dialog_content = "E agora você está me imitando! Urgh... Você realmente é imaturo, sabia disso?",
  ui_story_5079_50790200_47_dialog_content = "Terminei de discutir com essa criança. Tenho muitas compras para fazer e ainda preciso visitar várias lojas e comparar os preços.",
  ui_story_5079_50790200_48_dialog_content = "... E-Espere!",
  ui_story_5079_50790200_49_dialog_content = "E agora?",
  ui_story_5079_50790200_50_dialog_content = "Você está aqui para comprar ingredientes, certo? Isso é o que o negócio da minha família faz! Gostaria de vir à nossa loja?",
  ui_story_5079_50790200_51_dialog_content = "Agora você quer o meu negócio depois de toda essa discussão? Desculpe, mas não estou interessado.",
  ui_story_5079_50790200_52_dialog_content = "<size=30>*suspiro* Outro fracasso...</size>",
  ui_story_5079_50790200_53_dialog_content = "(Pai sempre diz que não podemos nos dar ao luxo de desistir de oportunidades de fazer negócios com clientes ricos como ela...)",
  ui_story_5079_50790200_54_dialog_content = "(Se eu conseguir fazer com que ela venha à nossa loja... Aposto que o pai vai me elogiar muito! Talvez ele até esqueça tudo o que aconteceu nos últimos dias.)",
  ui_story_5079_50790200_55_dialog_content = "(Mas o mais importante, posso usar isso como uma chance de me livrar de tudo que eu não gosto de comer... Heeheehee!)",
  ui_story_5079_50790200_56_dialog_content = "E-Eu sempre posso pedir ao meu pai para te dar um desconto incrível! Pense nisso como a minha maneira de compensar você!",
  ui_story_5079_50790200_57_dialog_content = "Você não estava tentando fugir de casa? Por que você traria um estranho para casa e pediria um desconto?",
  ui_story_5079_50790200_58_dialog_content = "Se eu fosse seu pai, nunca concordaria com algo assim.",
  ui_story_5079_50790200_59_dialog_content = "*soluços* O-O que devo fazer?",
  ui_story_5079_50790200_60_dialog_content = "Entendi! Vou dizer a ele que você estava preocupado com a minha segurança, então me trouxe para casa! Ele ficará tão grato que lhe oferecerá um negócio único na vida!",
  ui_story_5079_50790200_61_dialog_content = "Isso faz sentido... Eu suponho que uma boa ação não poderia machucar.",
  ui_story_5079_50790200_62_dialog_content = "Apenas lembre-se, eu não posso prometer que farei negócios com sua família. Mostre o caminho, garoto.",
  ui_story_5079_50790200_63_dialog_content = "Hã? O que é aquela coisa atrás de você?",
  ui_story_5079_50790200_64_dialog_content = "Você finalmente notou, hein? Não é tarde demais para ter medo, sabe! Especialmente agora que você sabe o que vai acontecer se me deixar com raiva...",
  ui_story_5079_50790200_65_dialog_content = "Uau, é tão fofo! E olha, ele pode se mover sozinho! Posso acariciá-lo? Posso?",
  ui_story_5079_50790200_66_dialog_content = "Ei, pare com isso! Isso não é um brinquedo!",
  ui_story_5079_50790200_67_dialog_content = "Por que você está ficando tão chateado? Eu só queria acariciar seu pequeno amigo...",
  ui_story_5079_50790200_68_dialog_content = "\"Meu 'pequeno amigo'? Você acha que a Pedra de Caça é... Urgh, esqueça.",
  ui_story_5079_50790200_69_dialog_content = "Arrase, garoto, mas você vai me dar um desconto ainda maior cada vez que acariciá-lo.",
  ui_story_5079_50790200_70_dialog_content = "O-Ok então... Eu só vou acariciá-lo uma vez...",
  ui_story_5079_50790200_71_dialog_content = "!",
  ui_story_5079_50790200_72_dialog_content = "Uau, é tão adorável! Ele se aconchegou em mim, então esses últimos carinhos não contam!",
  ui_story_5079_50790200_73_dialog_content = "!",
  ui_story_5079_50790200_74_dialog_content = "(A Pedra de Caça deixou ela tocá-la? Por que, você roda inútil!)",
  ui_story_5079_50790200_75_dialog_content = "Tudo bem, isso é o suficiente! Vamos indo!",
  ui_story_5079_50790300_1_dialog_content = "Hum, hum, hum!",
  ui_story_5079_50790300_2_dialog_content = "... Por que você está tão feliz?",
  ui_story_5079_50790300_3_dialog_content = "Você é o primeiro grande cliente que eu já trouxe para casa, então é claro que estou feliz! Papai vai ficar tão satisfeito comigo!",
  ui_story_5079_50790300_4_dialog_content = "Você costuma ajudar nos negócios da sua família?",
  ui_story_5079_50790300_5_dialog_content = "Sim... Mas eu geralmente só atrapalho. Na verdade, acho que sou o motivo da nossa loja estar indo tão mal ultimamente.",
  ui_story_5079_50790300_6_dialog_content = "Mas agora que você está aqui, as coisas finalmente podem melhorar para nós!",
  ui_story_5079_50790300_7_dialog_content = "... Eu nem ao menos sei o seu nome, criança.",
  ui_story_5079_50790300_8_dialog_content = "Eu?",
  ui_story_5079_50790300_9_dialog_content = "Uhh?",
  ui_story_5079_50790300_10_dialog_content = "Meu nome é... <color=#FFB400>Popo</color>.",
  ui_story_5079_50790300_11_dialog_content = "Ah, não tenha ideias malucas! É só um nome! Um nome perfeitamente normal!",
  ui_story_5079_50790300_12_dialog_content = "Eu não ia dar uma segunda pensada nisso, mas já que você fez disso um grande problema, agora eu meio que quero perguntar...",
  ui_story_5079_50790300_13_dialog_content = "É um nome bem fofo, sabe.",
  ui_story_5079_50790300_14_dialog_content = "Tudo bem, já chega! Não estamos aqui para discutir a fofura dos nomes, agora vamos!",
  ui_story_5079_50790300_15_dialog_content = "Este é o lugar!",
  ui_story_5079_50790300_16_dialog_content = "Sério? Não parece muito profissional...",
  ui_story_5079_50790300_17_dialog_content = "Hmm... Pai? Você está em casa?",
  ui_story_5079_50790300_18_dialog_content = "Bem, não quero ser rude, mas há um sinal de \"fechado\" postado na porta.",
  ui_story_5079_50790300_19_dialog_content = "Parece que sua loja não abre há um tempo. Você não estava ciente disso?",
  ui_story_5079_50790300_20_dialog_content = "?",
  ui_story_5079_50790300_21_dialog_content = "Eu não tenho ideia do que está falando!",
  ui_story_5079_50790300_22_dialog_content = "Meu pai ama sua loja e a mantém aberta todos os dias do ano! Como poderia estar fechada?",
  ui_story_5079_50790300_23_dialog_content = "Por que você não dá uma olhada por si mesmo? Diz aqui, \"Loja fechada por motivos familiares.\"",
  ui_story_5079_50790300_24_dialog_content = "(Eu sabia que não deveria ter me envolvido com essa criança. Já perdi muito tempo.)",
  ui_story_5079_50790300_25_dialog_content = "(Se eu não conseguir fazer isso perfeitamente, quem sabe o quanto eles vão zombar de mim...)",
  ui_story_5079_50790300_26_dialog_content = "Desculpe, Popo, mas não posso fazer negócios com sua família se não há negócio algum. Eu deveria ir-",
  ui_story_5079_50790300_27_dialog_content = "*chorando*... <size=45>Uaaaaaaaaahhh!</size>",
  ui_story_5079_50790300_28_dialog_content = "Ei, não chore! As pessoas vão pensar que estou te provocando!",
  ui_story_5079_50790300_29_dialog_content = "Isso é porque você ESTÁ pegando no meu pé!",
  ui_story_5079_50790300_30_dialog_content = "Se eu não tivesse perdido meu trem, já teria ido embora há muito tempo! Então eu nunca teria descoberto que meu pai realmente não me quer mais!",
  ui_story_5079_50790300_31_dialog_content = "Mas ainda assim, chorar não resolverá nada. Você tem mais alguém para contar além do seu pai?",
  ui_story_5079_50790300_32_dialog_content = "Não... Minha mãe faleceu há muito tempo. Pai e eu temos cuidado um do outro desde então...",
  ui_story_5079_50790300_33_dialog_content = "Mas nós discutimos o tempo todo... E durante nossa última briga, ele disse que não precisava de uma filha desobediente como eu.",
  ui_story_5079_50790300_34_dialog_content = "Eu também estava furioso com ele! Tão furioso que fugi de casa...",
  ui_story_5079_50790300_35_dialog_content = "Eu não fazia ideia de que ele realmente iria embora... Pai realmente não me ama mais... Waaaaah!",
  ui_story_5079_50790300_36_dialog_content = "Mas é normal discutir com seu pai, não é?",
  ui_story_5079_50790300_37_dialog_content = "*cheira*... Isso significa que você também discute com seu pai?",
  ui_story_5079_50790300_38_dialog_content = "Eu fiz, e foi bem ruim também. Ele se recusou a me aceitar ou a minha Hunting Stone aqui - a que você acha tão fofa.",
  ui_story_5079_50790300_39_dialog_content = "...",
  ui_story_5079_50790300_40_dialog_content = "Então ele me deixou algum dinheiro, e então eu nunca mais o vi...",
  ui_story_5079_50790300_41_dialog_content = "Huh? Você quer dizer que seu pai realmente deixou algum dinheiro para você?",
  ui_story_5079_50790300_42_dialog_content = "Mas meu pai não me deixou nada antes de me abandonar!",
  ui_story_5079_50790300_43_dialog_content = "<size=50>Uaaaaaaaaaah!</size>",
  ui_story_5079_50790300_44_dialog_content = "Não diga isso, Popo! Seu pai lhe deixou essa loja, não foi?",
  ui_story_5079_50790300_45_dialog_content = "Tenho quase certeza de que isso faz de você o chefe por aqui, certo? Se sim, posso comprar essa mesa de chocolate de você? Estou com bastante fome!",
  ui_story_5079_50790300_46_dialog_content = "Parece um pouco duro, mas aposto que é delicioso. Olha, até tem uma camada de cobertura em cima!",
  ui_story_5079_50790300_47_dialog_content = "Oh? O vidro naquele armário é feito de açúcar mascavo caramelizado?",
  ui_story_5079_50790300_48_dialog_content = "E aquele vaso é na verdade um pote de mel! Posso mergulhar isso no mel? O vaso também parece bem gostoso...",
  ui_story_5079_50790300_49_dialog_content = "Ahhhh! Pare de tentar comer os móveis! Esta ainda é minha casa, você sabe!",
  ui_story_5079_50790300_50_dialog_content = "Você realmente não tem modos nenhum, nem gosto, aliás!",
  ui_story_5079_50790300_51_dialog_content = "Quero dizer, que tipo de pessoa mergulha doce duro no mel? Você está tentando estragar seus dentes?",
  ui_story_5079_50790300_52_dialog_content = "Ah bom, você não está chorando mais.",
  ui_story_5079_50790300_53_dialog_content = "Hã? Você estava tentando me animar?",
  ui_story_5079_50790300_54_dialog_content = "Não, eu estou realmente, realmente com fome.",
  ui_story_5079_50790300_55_dialog_content = "Bem... Isso ainda não é desculpa para você comer nossos móveis!",
  ui_story_5079_50790300_56_dialog_content = "Ainda temos muitas cenouras em estoque, então fique à vontade para pegá-las.",
  ui_story_5079_50790300_57_dialog_content = "Cenouras? Eca...",
  ui_story_5079_50790300_58_dialog_content = "O quê? Você também não gosta de cenouras?",
  ui_story_5079_50790300_59_dialog_content = "Isso nem chega perto de descrever o meu ódio por eles... As cenouras são a comida mais assustadora do mundo!",
  ui_story_5079_50790300_60_dialog_content = "Eu sei! Eu sei!",
  ui_story_5079_50790300_61_dialog_content = "As cenouras nem deveriam existir neste mundo! Elas foram o motivo inteiro de eu ter brigado com meu pai!",
  ui_story_5079_50790300_62_dialog_content = "Ele disse que era inaceitável para a filha de um vendedor de cenouras odiar comer cenouras, e que eu estava trazendo vergonha para o negócio da nossa família...",
  ui_story_5079_50790300_63_dialog_content = "Mas não há regra que diga que eu tenho que gostar de cenouras só porque meu pai as vende para viver!",
  ui_story_5079_50790300_64_dialog_content = "Heh, eu não esperava concordar completamente com você em nada, mas aqui estamos.",
  ui_story_5079_50790300_65_dialog_content = "Você estava planejando vender todas as cenouras da sua família para mim, para não ter que comê-las, não é?",
  ui_story_5079_50790300_66_dialog_content = "Bem, não... Eu só ia vender metade deles e deixar o resto para o meu pai, já que ele gosta tanto deles.",
  ui_story_5079_50790300_67_dialog_content = "Ele faz, huh... Não é à toa que ele te chamou de \"Popo\"! Aposto que é porque ele queria que você também amasse cenouras!",
  ui_story_5079_50790300_68_dialog_content = "Humph! Não há nada de errado em não gostar de cenouras! Ele poderia ter me chamado de \"Cenoura\", e eu ainda acharia nojento!",
  ui_story_5079_50790300_69_dialog_content = "Então, mesmo depois de tudo o que aconteceu, você ainda quer deixar algumas cenouras para o seu pai comer?",
  ui_story_5079_50790300_70_dialog_content = "Ah... Essa era a minha ideia antes, mas não mais! Vou me livrar de todas essas cenouras fedorentas agora!",
  ui_story_5079_50790300_71_dialog_content = "Você ainda ama seu pai?",
  ui_story_5079_50790300_72_dialog_content = "C-Claro que não! Por que eu me importaria com ele depois que ele me abandonou assim? Humph!",
  ui_story_5079_50790300_73_dialog_content = "Mas e se ele não te abandonou de fato?",
  ui_story_5079_50790300_74_dialog_content = "Bem, uh... Teremos que esperar para ver!",
  ui_story_5079_50790300_75_dialog_content = "(As crianças são muito previsíveis... Eu não acho que o pai dela seja tão malvado quanto ela diz.)",
  ui_story_5079_50790300_76_dialog_content = "(Ele provavelmente está apenas tentando impor suas preferências à sua filha, o que é por isso que eles brigam tanto. É um erro, mas um erro que ele comete por amor.)",
  ui_story_5079_50790300_77_dialog_content = "(Uma pequena lacuna como essa é fácil de ser preenchida.)",
  ui_story_5079_50790300_78_dialog_content = "Parece que seus problemas com seu pai são bem pequenos, pelo menos comparados aos meus.",
  ui_story_5079_50790300_79_dialog_content = "Uma vez, quando meu pai tentou me forçar a comer cenouras, eu comi um punhado de pedras só para me vingar dele...",
  ui_story_5079_50790300_80_dialog_content = "Ah! Então é por isso que você estava tão pronto para comer aquelas pedras mais cedo!",
  ui_story_5079_50790300_81_dialog_content = "Não tinha nada a ver com você ser imaturo ou não ter gosto nenhum!",
  ui_story_5079_50790300_82_dialog_content = "... Será que te mataria ser mais educado de vez em quando? Lembre-se, você é o que me deve!",
  ui_story_5079_50790400_1_dialog_content = "Já se sente melhor? Deveria, depois de toda essa conversa...",
  ui_story_5079_50790400_2_dialog_content = "Lembre-se, toda nuvem escura tem um forro prateado. Podemos ter sido abandonados, mas pelo menos agora somos livres.",
  ui_story_5079_50790400_3_dialog_content = "E se meu pai não tivesse me deixado, eu nunca teria conhecido... Deixa pra lá, você ainda é muito jovem para saber sobre isso.",
  ui_story_5079_50790400_4_dialog_content = "Eu não me importo com isso!",
  ui_story_5079_50790400_5_dialog_content = "Eu não vou aceitar isso calado! Eu vou me vingar do pai!",
  ui_story_5079_50790400_6_dialog_content = "Acha que eu poderia pegar seu volante por um tempo? Eu quero usá-lo para atropelá-lo algumas vezes!",
  ui_story_5079_50790400_7_dialog_content = "...",
  ui_story_5079_50790400_8_dialog_content = "... Eu te disse, é chamada de Pedra de Caça.",
  ui_story_5079_50790400_9_dialog_content = "E embora eu adoraria emprestá-lo a você... ele se recusa a sair do meu lado, nunca.",
  ui_story_5079_50790400_10_dialog_content = "Além disso, você não deveria se preocupar tanto com isso, Popo. Algo me diz que seu pai não te abandonou de verdade.",
  ui_story_5079_50790400_11_dialog_content = "Mas eu contei a todos vocês sobre o que aconteceu...",
  ui_story_5079_50790400_12_dialog_content = "Sim, depois de ver a loja e pensar um pouco, acho que tenho uma boa ideia do que está acontecendo.",
  ui_story_5079_50790400_13_dialog_content = "Viu? As cenouras nestes montes estão claramente ainda frescas. Isso me diz que acabaram de chegar, e ele estava se preparando para vendê-las.",
  ui_story_5079_50790400_14_dialog_content = "Além disso, nenhum dos objetos de valor em sua casa está faltando. Isso não é algo que eu faria se estivesse planejando ir embora.",
  ui_story_5079_50790400_15_dialog_content = "Ele não deixaria todas as suas posses espalhadas assim a menos que...",
  ui_story_5079_50790400_16_dialog_content = "A menos que?",
  ui_story_5079_50790400_17_dialog_content = "A menos que ele tivesse tanta dívida que não conseguisse pagar tudo de volta. Ele pode evitar suspeitas e escapar muito mais facilmente se deixar tudo exatamente como está.",
  ui_story_5079_50790400_18_dialog_content = "Ah...",
  ui_story_5079_50790400_19_dialog_content = "O-O que há com esse olhar?",
  ui_story_5079_50790400_20_dialog_content = "Para alguém tão imaturo quanto você, não fazia ideia de que poderia ser tão racional!",
  ui_story_5079_50790400_21_dialog_content = "Ainda me chamando de imaturo, huh...",
  ui_story_5079_50790400_22_dialog_content = "Vamos deixar pra lá. Discutir sobre isso só nos torna imaturos.",
  ui_story_5079_50790400_23_dialog_content = "Mas agora que você mencionou...",
  ui_story_5079_50790400_24_dialog_content = "Tenho quase certeza de que meu pai realmente pegou dinheiro emprestado de... a <color=#FFB400>Família Ketchup</color>!",
  ui_story_5079_50790400_25_dialog_content = "Mas essa dívida deveria ter sido paga há muito tempo! Será que o pai poderia ter emprestado mais dinheiro sem me contar?",
  ui_story_5079_50790400_26_dialog_content = "Eu dificilmente acho que seu pai tem alguma necessidade de te contar sobre as dívidas dele...",
  ui_story_5079_50790400_27_dialog_content = "É isso! Já tomei minha decisão!",
  ui_story_5079_50790400_28_dialog_content = "Ótimo... E qual seria essa decisão brilhante?",
  ui_story_5079_50790400_29_dialog_content = "Vou visitar a família Ketchup! Eles podem até saber onde meu pai está agora!",
  ui_story_5079_50790400_30_dialog_content = "Oh? Na verdade, é uma boa ideia.",
  ui_story_5079_50790400_31_dialog_content = "(Finalmente posso parar de cuidar dessa criança agora...)",
  ui_story_5079_50790400_32_dialog_content = "Espero que a Família Ketchup tenha as respostas que você está procurando, criança. Agora, eu realmente deveria estar...",
  ui_story_5079_50790400_33_dialog_content = "E-Espere! Você não pode ir embora ainda!",
  ui_story_5079_50790400_34_dialog_content = "Uhh?",
  ui_story_5079_50790400_35_dialog_content = "Heheh, tem um motivo para eu continuar te chamando de imaturo, sabe?",
  ui_story_5079_50790400_36_dialog_content = "Se você sair agora, vai se arrepender pelo resto da sua vida!",
  ui_story_5079_50790400_37_dialog_content = "E por que é que?",
  ui_story_5079_50790400_38_dialog_content = "A Família Ketchup sempre esteve no comando desta cidade. Eles também administram a maior loja de tomates de toda Astra!",
  ui_story_5079_50790400_39_dialog_content = "Se você está procurando os melhores ingredientes, não pode perder!",
  ui_story_5079_50790400_40_dialog_content = "Você deve ter feito sua pesquisa antes de vir para Folta, não é? Não é mesmo?",
  ui_story_5079_50790400_41_dialog_content = "Temos um velho ditado por aqui: \"Qualquer um que venha a Folta sem fazer negócios com a Família Ketchup é um tolo!\"",
  ui_story_5079_50790400_42_dialog_content = "Você tem certeza de que não está apenas inventando esse \"ditado antigo\", criança?",
  ui_story_5079_50790400_43_dialog_content = "De qualquer forma, estou me sentindo bastante generoso hoje! Venha comigo, e eu vou te apresentar pessoalmente à Família Ketchup!",
  ui_story_5079_50790400_44_dialog_content = "\"Generoso\", é? Você está apenas com muito medo de vê-los sozinho, não está?",
  ui_story_5079_50790400_45_dialog_content = "Afinal, tenho certeza que uma família rica como essa não tem tempo para crianças pequenas como você...",
  ui_story_5079_50790400_46_dialog_content = "E você achou que estava pronto para fugir de casa...",
  ui_story_5079_50790400_47_dialog_content = "Th-Isso não é verdade! E-Eu só estou fazendo isso por sua causa...",
  ui_story_5079_50790400_48_dialog_content = "Humph, bem, você pode esquecer tudo agora! Divirta-se sendo uma tola, senhora, e eu vou vê-los todos sozinho!",
  ui_story_5079_50790400_49_dialog_content = "Então agora eu sou imaturo E um tolo...",
  ui_story_5079_50790400_50_dialog_content = "Tsk! Pequenas encrenqueiras como ela simplesmente precisam aprender as coisas do jeito difícil.",
  ui_story_5079_50790400_51_dialog_content = "Argh, mas por que estou tão inquieto?",
  ui_story_5079_50790400_52_dialog_content = "Se ela não estivesse mentindo sobre a Família Ketchup, então eu definitivamente teria que fazer uma visita a eles.",
  ui_story_5079_50790400_53_dialog_content = "Além disso, não tenho certeza se Popo irá muito longe com esse temperamento dela. Se algo acontecer com ela...",
  ui_story_5079_50790400_54_dialog_content = "Na verdade, não estou preocupado com ela ou algo assim... mas muitas pessoas nos viram juntos mais cedo.",
  ui_story_5079_50790400_55_dialog_content = "Se algo acontecer com ela, cada pessoa nessa cidadezinha vai vir atrás de mim, já que sou um forasteiro...",
  ui_story_5079_50790400_56_dialog_content = "Ei, Popo! Espere!",
  ui_story_5079_50790400_57_dialog_content = "Humph! Eu te conheço?",
  ui_story_5079_50790400_58_dialog_content = "Acontece que eu também estou indo por este caminho. Quer caminhar juntos?",
  ui_story_5079_50790400_59_dialog_content = "Não!",
  ui_story_5079_50790400_60_dialog_content = "Embora... Se você me implorar para deixar você caminhar comigo, eu posso reconsiderar.",
  ui_story_5079_50790400_61_dialog_content = "Como eu disse, apenas acontece de eu estar indo na mesma direção...",
  ui_story_5079_50790400_62_dialog_content = "Que tal isso? Você caminha comigo, e eu te ajudo a perguntar à Família Ketchup sobre seu pai.",
  ui_story_5079_50790400_63_dialog_content = "Você é uma garota bastante inteligente, então tenho certeza de que fará a escolha certa.",
  ui_story_5079_50790400_64_dialog_content = "Hum...",
  ui_story_5079_50790400_65_dialog_content = "Tudo bem, mas você tem que andar atrás de mim o tempo todo!",
  ui_story_5079_50790400_66_dialog_content = "E não se perca! Não estou com vontade de te procurar se você se perder!",
  ui_story_5079_50790400_67_dialog_content = "(Crianças são uma grande dor de cabeça...)",
  ui_story_5079_50790400_68_dialog_content = "Tá bom, vamos.",
  ui_story_5079_50790500_1_dialog_content = "B-Bem... A-Aqui estamos! V-Vamos entrar!",
  ui_story_5079_50790500_2_dialog_content = "Você está bem? Você está gaguejando muito... Você não está nervoso, está?",
  ui_story_5079_50790500_3_dialog_content = "C-Claro que não! Eu-Eu só estou um pouco animado, só isso.",
  ui_story_5079_50790500_4_dialog_content = "Afinal, estamos nos encontrando com a chefe da Família Ketchup... Eu... Eu tenho muito respeito por ela!",
  ui_story_5079_50790500_5_dialog_content = "Mas ir à casa dela sem ser convidado e vestido assim... V-Você acha que vou causar uma má impressão nela?",
  ui_story_5079_50790500_6_dialog_content = "Você se preocupa muito para alguém da sua idade, Popo.",
  ui_story_5079_50790500_7_dialog_content = "Mas você vai ficar bem. Apenas fique atrás de mim e deixe-me falar por você.",
  ui_story_5079_50790500_8_dialog_content = "Ah, vejo que temos um convidado de longe. Bem-vinda, minha senhora.",
  ui_story_5079_50790500_9_dialog_content = "Vejo que você trouxe alguém com você... um pequenino que parece familiar.",
  ui_story_5079_50790500_10_dialog_content = "Devo dizer, vocês dois formam uma dupla bastante interessante. Me diga, o que os traz aqui hoje?",
  ui_story_5079_50790500_11_dialog_content = "Eu vim porque... Espere um minuto, já nos encontramos antes?",
  ui_story_5079_50790500_12_dialog_content = "Acredito que a senhora esteja enganada. Embora eu tenha recebido muitos convidados até agora...",
  ui_story_5079_50790500_13_dialog_content = "Tenho certeza de que me lembraria de uma jovem tão bela e de aparência nobre como você.",
  ui_story_5079_50790500_14_dialog_content = "I-É mesmo...",
  ui_story_5079_50790500_15_dialog_content = "(Eu sabia que comprar essas roupas era a coisa certa a fazer! Hora de arriscar um pouco...)",
  ui_story_5079_50790500_16_dialog_content = "*olha*",
  ui_story_5079_50790500_17_dialog_content = "<size=30>Eu sei, eu sei! Eu te dei minha palavra, agora pare de me olhar assim!</size>",
  ui_story_5079_50790500_18_dialog_content = "Ahem... Meus motivos para vir aqui são duplos...",
  ui_story_5079_50790500_19_dialog_content = "Uma dessas razões é que essa garota afirma que seu pai a abandonou. Suspeitamos que sua família esteja de alguma forma conectada a este assunto, então viemos perguntar.",
  ui_story_5079_50790500_20_dialog_content = "... Ei! Não seja tão direto sobre isso!",
  ui_story_5079_50790500_21_dialog_content = "Isso é um mal-entendido bastante bizarro.",
  ui_story_5079_50790500_22_dialog_content = "Você quer dizer que seu pai ainda não te encontrou, Popo?",
  ui_story_5079_50790500_23_dialog_content = "Me achou?",
  ui_story_5079_50790500_24_dialog_content = "Sim. Depois de procurar por você em todos os lugares, ele concluiu que você já havia partido em um trem, então ele comprou um bilhete para a próxima viagem de saída.",
  ui_story_5079_50790500_25_dialog_content = "E ainda assim, aqui está você. Uma reviravolta divertida do destino, você não concorda?",
  ui_story_5079_50790500_26_dialog_content = "Sério? Sério? Pai só fechou a loja para que ele pudesse vir me procurar?",
  ui_story_5079_50790500_27_dialog_content = "Claro. Quem mais cuidaria da loja na ausência dele?",
  ui_story_5079_50790500_28_dialog_content = "M-M-Mas então...",
  ui_story_5079_50790500_29_dialog_content = "Como eu deveria encontrá-lo? Quem sabe o quão longe ele está indo de trem... Eu nunca teria tentado fugir se soubesse que isso aconteceria...",
  ui_story_5079_50790500_30_dialog_content = "Não se preocupe, Popo.",
  ui_story_5079_50790500_31_dialog_content = "O condutor do trem é parte da Família Ketchup. Vou pedir a ele para dizer ao seu pai para voltar para casa o mais rápido possível.",
  ui_story_5079_50790500_32_dialog_content = "Sério? Sério? Ah, muito obrigado!",
  ui_story_5079_50790500_33_dialog_content = "(Ufa... Isso é uma coisa a menos para se preocupar.)",
  ui_story_5079_50790500_34_dialog_content = "(O pai de Popo estava disposto a fechar seu negócio, conquistado com tanto esforço, apenas para procurar sua filha.)",
  ui_story_5079_50790500_35_dialog_content = "(Se fosse meu pai, humph, ele provavelmente se sentiria aliviado.)",
  ui_story_5079_50790500_36_dialog_content = "Isso me lembra, senhora! Esta imatura... Quer dizer, sofisticada mocinha veio a Folta a negócios importantes!",
  ui_story_5079_50790500_37_dialog_content = "Ei, ninguém te pediu para se intrometer...",
  ui_story_5079_50790500_38_dialog_content = "Ela precisa comprar muitos ingredientes de primeira linha, então pensei que deveria trazê-la para te ver primeiro!",
  ui_story_5079_50790500_39_dialog_content = "Você definitivamente pode ajudá-la, não pode?",
  ui_story_5079_50790500_40_dialog_content = "(Oh... É assim que a Popo me agradece? Acho que vou deixá-la terminar então...)",
  ui_story_5079_50790500_41_dialog_content = "(Além disso... eu poderia me acostumar a ser chamada de \"senhora sofisticada.\")",
  ui_story_5079_50790500_42_dialog_content = "Obrigado, Popo. Eu ficaria mais do que feliz em organizar algo.",
  ui_story_5079_50790500_43_dialog_content = "Com a posição da Família Ketchup em Folta, posso fazer com que todas as lojas enviem seus melhores ingredientes para a sua seleção.",
  ui_story_5079_50790500_44_dialog_content = "Depois de uma jornada tão longa, duvido que você queira correr pela cidade procurando por eles.",
  ui_story_5079_50790500_45_dialog_content = "E já que você foi gentil o suficiente para ajudar o pequeno Popo, eu posso ajudá-lo a comprá-los pelos preços mais baixos possíveis. Isso seria satisfatório?",
  ui_story_5079_50790500_46_dialog_content = "Se não for pedir muito, então sim, com certeza!",
  ui_story_5079_50790500_47_dialog_content = "Vou deixar minha lista de compras com você, ahem, muito obrigado pela sua ajuda.",
  ui_story_5079_50790500_48_dialog_content = "Não se preocupe com isso. Começarei a reunir esses itens imediatamente.",
  ui_story_5079_50790500_49_dialog_content = "Hehehe!",
  ui_story_5079_50790500_50_dialog_content = "Você parece muito satisfeito, Popo.",
  ui_story_5079_50790500_51_dialog_content = "Bem, eu acabei de te ajudar a fechar um ótimo negócio. Espero que esteja pronto para me compensar depois!",
  ui_story_5079_50790500_52_dialog_content = "Tenho certeza de que poderia ter feito isso sozinho... deixa pra lá.",
  ui_story_5079_50790500_53_dialog_content = "A verdade é, você realmente me ajudou. Como você quer que eu te retribua?",
  ui_story_5079_50790500_54_dialog_content = "Que tal ficar por aqui até eu encontrar meu pai?",
  ui_story_5079_50790500_55_dialog_content = "Huh... Você quer dizer que devo cuidar de você um pouco mais? Claro, criança.",
  ui_story_5079_50790500_56_dialog_content = "V-Você não está \"me vigiando\"! Estamos nos ajudando, ok?",
  ui_story_5079_50790500_57_dialog_content = "E eu te ajudei muito, lembra? Você tem que pelo menos retribuir!",
  ui_story_5079_50790500_58_dialog_content = "Então, deixe-me tornar a proposta mais atraente com uma oferta que você não pode recusar.",
  ui_story_5079_50790500_59_dialog_content = "Quando seu pai voltar, vou convencê-lo a parar de te fazer comer cenouras.",
  ui_story_5079_50790500_60_dialog_content = "Estou bastante familiarizado com esse tipo de coisa, especialmente quando se trata de persuadir e importunar. Também ajuda que eu tenho setenta e quatro razões pelas quais as cenouras não devem ser comidas.",
  ui_story_5079_50790500_61_dialog_content = "Sério? Isso é incrível! Até agora, só consegui pensar em trinta e três razões...",
  ui_story_5079_50790500_62_dialog_content = "Se você realmente conseguir realizar isso... Serei seu seguidor para a vida toda!",
  ui_story_5079_50790500_63_dialog_content = "Perdoe-me, mas a senhora da casa preparou uma refeição deliciosa para nossos dois estimados convidados. Por favor, siga-me até a sala de jantar, se quiser.",
  ui_story_5079_50790500_64_dialog_content = "Esta será a oportunidade perfeita para você experimentar as diferentes iguarias da nossa cidade também, minha senhora. Se tiver alguma sugestão sobre a comida, por favor, compartilhe-as conosco de maneira respeitosa.",
  ui_story_5079_50790500_65_dialog_content = "Caso você não demonstre o nível adequado de respeito para com nosso povo, especialmente o chefe da Família Ketchup...",
  ui_story_5079_50790500_66_dialog_content = "Eu posso ter que tomar medidas contra você.",
  ui_story_5079_50790500_67_dialog_content = "Eu acho que você não precisa ir tão longe, precisa?",
  ui_story_5079_50790500_68_dialog_content = "Escolhi fazer negócios com a Família Ketchup por um senso de confiança mútua.",
  ui_story_5079_50790500_69_dialog_content = "Então, por favor, me perdoe por minhas insinuações insensíveis... Mas há uma sensação de inquietação no meu coração que não vai embora...",
  ui_story_5079_50790500_70_dialog_content = "Em qualquer caso, por aqui.",
  ui_story_5079_50790500_71_dialog_content = "Finalmente vou comer! Estive me perguntando todo esse tempo como é o sabor da comida de Folta...",
  ui_story_5079_50790500_72_dialog_content = "Hehehe!",
  ui_story_5079_50790500_73_dialog_content = "Você realmente não sabe como esconder suas emoções, não é? Lembre-se, estamos jantando com o chefe da Família Ketchup.",
  ui_story_5079_50790500_74_dialog_content = "Tente agir um pouco mais como uma dama, você poderia?",
  ui_story_5079_50790500_75_dialog_content = "Agora você também está me dando sermão? Você soa tão irritante quanto meu pai...",
  ui_story_5079_50790500_76_dialog_content = "De qualquer forma, você sabe o que significa jantar com a Família Ketchup, não sabe?",
  ui_story_5079_50790500_77_dialog_content = "Isso significa que tudo é feito com tomates! O que também significa que não haverá uma única cenoura fedorenta à vista!",
  ui_story_5079_50790500_78_dialog_content = "Isso é definitivamente algo para se esperar, mas... eu realmente soei como seu pai agora?",
  ui_story_5079_50790500_79_dialog_content = "Sim. Ele sempre me diz como me comportar à mesa, não que eu o escute, no entanto!",
  ui_story_5079_50790500_80_dialog_content = "Você deveria estar feliz que finalmente vamos comer, então pare de pensar demais nas coisas!",
  ui_story_5079_50790500_81_dialog_content = "Eu sei, eu só...",
  ui_story_5079_50790500_82_dialog_content = "(Eu só não quero me tornar outro adulto teimoso assim...)",
  ui_story_5079_50790500_83_dialog_content = "Por favor, nos perdoe se a refeição não for tão grandiosa quanto esperado. Nossos chefs fizeram o máximo que puderam o mais rápido possível.",
  ui_story_5079_50790500_84_dialog_content = "Não se preocupe, todos esses pratos vermelhos são suficientes para abrir o meu apetite!",
  ui_story_5079_50790500_85_dialog_content = "Podemos comer agora? Podemos?",
  ui_story_5079_50790500_86_dialog_content = "Por favor, ajudem-se.",
  ui_story_5079_50790500_87_dialog_content = "Eu quero experimentar a bisque de tomate primeiro! Só de pensar naquele sabor doce e azedo, minha boca enche de água!",
  ui_story_5079_50790500_88_dialog_content = "Espere, vamos fazer isso juntos! Três, dois, um, vamos!",
  ui_story_5079_50790500_89_dialog_content = "Por favor, não me faça fazer algo tão idiota...",
  ui_story_5079_50790500_90_dialog_content = "Vamos! Por favor?",
  ui_story_5079_50790500_91_dialog_content = "Bom... Três, dois...",
  ui_story_5079_50790500_92_dialog_content = "Um!",
  ui_story_5079_50790500_93_dialog_content = "*suspira*",
  ui_story_5079_50790500_94_dialog_content = "...",
  ui_story_5079_50790500_95_dialog_content = "...",
  ui_story_5079_50790500_96_dialog_content = "<size=45>Pfffffffft!</size>",
  ui_story_5079_50790500_97_dialog_content = "Está envenenado! A sopa está envenenada! Alguém está tentando nos eliminar!",
  ui_story_5079_50790500_98_dialog_content = "Isso é absolutamente inaceitável! Seu pessoal fez isso de propósito?",
  ui_story_5079_50790500_99_dialog_content = "Recuso-me a acreditar que a culinária da Família Ketchup seja desagradável ao ponto de ser intragável.",
  ui_story_5079_50790500_100_dialog_content = "Tem certeza de que vocês dois não estão exagerando?",
  ui_story_5079_50790500_101_dialog_content = "Não é uma questão de gosto! Por que diabos vocês colocariam cenouras na sopa de tomate?",
  ui_story_5079_50790500_102_dialog_content = "Cenouras? Impossível. Não guardamos esse tipo de ingrediente em nossas despensas.",
  ui_story_5079_50790500_103_dialog_content = "Também sou uma testemunha aqui! Experimente por si mesma, senhora!",
  ui_story_5079_50790500_104_dialog_content = "...",
  ui_story_5079_50790500_105_dialog_content = "Muito bem então...",
  ui_story_5079_50790500_106_dialog_content = "*suspira*",
  ui_story_5079_50790500_107_dialog_content = "...",
  ui_story_5079_50790500_108_dialog_content = "Por favor, aceite minhas mais sinceras desculpas. Isso não é apenas sopa de tomate com cenouras.",
  ui_story_5079_50790500_109_dialog_content = "Na verdade, essa sopa tem gosto como se fosse feita inteiramente de cenouras.",
  ui_story_5079_50790500_110_dialog_content = "<color=#e8d9bb>Blegh! Blegh!</color>",
  ui_story_5079_50790500_111_dialog_content = "O que é esse barulho?",
  ui_story_5079_50790500_112_dialog_content = "Parece que está acontecendo uma grande agitação lá fora...",
  ui_story_5079_50790500_113_dialog_content = "...",
  ui_story_5079_50790500_114_dialog_content = "...",
  ui_story_5079_50790500_115_dialog_content = "...",
  ui_story_5079_50790500_116_dialog_content = "Por que...",
  ui_story_5079_50790500_117_dialog_content = "<size=50>Por que tudo agora tem gosto de cenoura?</size>",
  ui_story_5079_50790601_1_dialog_content = "Explique a situação atual.",
  ui_story_5079_50790601_2_dialog_content = "Há uma leve... ou melhor, uma grave perturbação na cidade...",
  ui_story_5079_50790601_3_dialog_content = "De repente, e por razões ainda desconhecidas, toda a comida em Folta agora tem gosto de cenouras - até as pedras e a poeira não foram poupadas.",
  ui_story_5079_50790601_4_dialog_content = "Temos alguma pista sobre esse fenômeno?",
  ui_story_5079_50790601_5_dialog_content = "A maioria dos moradores da cidade ainda está em estado de pânico, tornando difícil obter qualquer informação significativa.",
  ui_story_5079_50790601_6_dialog_content = "No entanto, alguns rumores começaram a surgir. Infelizmente... mencioná-los aqui seria um tanto inconveniente.",
  ui_story_5079_50790601_7_dialog_content = "Não importa isso, por favor compartilhe suas descobertas conosco.",
  ui_story_5079_50790601_8_dialog_content = "Alguns acreditam que isso é obra da loja de cenouras. Afinal, essa é a única loja que vende cenouras aqui em Folta.",
  ui_story_5079_50790601_9_dialog_content = "Para piorar a situação, a loja está atualmente fechada para negócios, e seu proprietário não está em lugar algum.",
  ui_story_5079_50790601_10_dialog_content = "Vários moradores acharam muito estranho para ser coincidência, então formaram um grupo de busca e tentaram encontrar o dono da loja e sua família para descobrir a verdade por trás de tudo isso.",
  ui_story_5079_50790601_11_dialog_content = "Então, parece que devemos localizar o pai de Popo antes que eles o façam... Diga-me, descobrimos algo sobre o paradeiro dele?",
  ui_story_5079_50790601_12_dialog_content = "Ainda não, minha senhora. Eu já tentei entrar em contato com o maestro.",
  ui_story_5079_50790601_13_dialog_content = "Perdoe-me... Mas ele ainda se recusa a receber qualquer uma das suas mensagens.",
  ui_story_5079_50790601_14_dialog_content = "Já se passou quase um século, e ele ainda está me ignorando?",
  ui_story_5079_50790601_15_dialog_content = "Ele é irritante como sempre, eu vejo.",
  ui_story_5079_50790601_16_dialog_content = "Então nossas únicas possíveis pistas agora...",
  ui_story_5079_50790601_17_dialog_content = "Huh? Não tenho ideia do que está acontecendo, mas eu juro que não fiz nada!",
  ui_story_5079_50790601_18_dialog_content = "Você viu agora mesmo, senhora. Até mesmo uma única mordida de cenoura é demais para mim!",
  ui_story_5079_50790601_19_dialog_content = "Então, por que eu iria me dar ao trabalho de fazer tudo na cidade ter o gosto deles?",
  ui_story_5079_50790601_20_dialog_content = "Posso confirmar a história dela. Popo estava comigo todo esse tempo e não teve tempo para fazer algo assim.",
  ui_story_5079_50790601_21_dialog_content = "Fique tranquilo, Popo, não tenho dúvidas sobre você.",
  ui_story_5079_50790601_22_dialog_content = "Seu pai, por outro lado... Me perdoe, mas—",
  ui_story_5079_50790601_23_dialog_content = "Meu pai é um comerciante perfeitamente honesto!",
  ui_story_5079_50790601_24_dialog_content = "Além disso, ele está me procurando agora porque acha que eu fugi de casa. Ele nunca faria algo tão horrível!",
  ui_story_5079_50790601_25_dialog_content = "Mas...",
  ui_story_5079_50790601_26_dialog_content = "Não há necessidade de dizer mais. Estou plenamente ciente da situação do pai dela.",
  ui_story_5079_50790601_27_dialog_content = "Duvidar dele é duvidar da veracidade das minhas próprias informações. Você tem outras pistas?",
  ui_story_5079_50790601_28_dialog_content = "Se ele é tão inocente quanto você acredita que ele seja, então só há uma outra possibilidade...",
  ui_story_5079_50790601_29_dialog_content = "Nossos relatórios indicam que apenas um único forasteiro está visitando Folta hoje e que sua chegada coincide em grande parte com os estranhos acontecimentos em nossa cidade.",
  ui_story_5079_50790601_30_dialog_content = "Alguns moradores acreditam fortemente que este forasteiro tem as respostas que eles procuram.",
  ui_story_5079_50790601_31_dialog_content = "...",
  ui_story_5079_50790601_32_dialog_content = "...",
  ui_story_5079_50790601_33_dialog_content = "Espere, por que está me olhando assim?",
  ui_story_5079_50790601_34_dialog_content = "Aquilo atrás de você parece conter um grande poder.",
  ui_story_5079_50790601_35_dialog_content = "Por favor, me perdoe... May Posso dar uma olhada mais de perto para que eu possa May livrá-lo de suspeitas?",
  ui_story_5079_50790601_36_dialog_content = "!",
  ui_story_5079_50790601_37_dialog_content = "Não ouse chegar perto da minha Pedra de Caça.",
  ui_story_5079_50790601_38_dialog_content = "Eu já te disse, vim para Folta para comprar ingredientes para um banquete. Como fazer tudo ter gosto de cenoura me beneficiaria de alguma forma?",
  ui_story_5079_50790601_39_dialog_content = "Você deve desculpar minha grosseria... Mas a verdade só será revelada através de um exame cuidadoso.",
  ui_story_5079_50790601_40_dialog_content = "Humph, é isso que a Família Ketchup chama de \"hospitalidade\"?",
  ui_story_5079_50790601_41_dialog_content = "Se for assim, deixe-me avisar: eu também não sou alguém que você queira irritar!",
  ui_story_5079_50790700_1_dialog_content = "As coisas ficaram um pouco fora de controle agora. Mas me acusar sem provas e até me atacar? Eu não aguentava mais.",
  ui_story_5079_50790700_2_dialog_content = "Aquele cara não te machucou, não é? Hunting Stone?",
  ui_story_5079_50790700_3_dialog_content = "...",
  ui_story_5079_50790700_4_dialog_content = "<color=#e8d9bb>*passos*</color>",
  ui_story_5079_50790700_5_dialog_content = "Eles alcançaram rapidamente, não é? Prepare-se, Pedra de Caça!",
  ui_story_5079_50790700_6_dialog_content = "Ahh!",
  ui_story_5079_50790700_7_dialog_content = "Ah, é apenas o Popo. Você pode relaxar agora, Pedra de Caça.",
  ui_story_5079_50790700_8_dialog_content = "...",
  ui_story_5079_50790700_9_dialog_content = "O que... O que você fez?",
  ui_story_5079_50790700_10_dialog_content = "Eu não pretendia te deixar para trás, mas aquelas pessoas eram—",
  ui_story_5079_50790700_11_dialog_content = "Você estava tão legal agora mesmo!",
  ui_story_5079_50790700_12_dialog_content = "Há?",
  ui_story_5079_50790700_13_dialog_content = "Você enfrentou toda a Família Ketchup sozinho! Eu nem sequer sonharia em fazer algo assim!",
  ui_story_5079_50790700_14_dialog_content = "Especialmente aquele conselheiro! Eu sempre tive muito medo daquele cara!",
  ui_story_5079_50790700_15_dialog_content = "Oh, você quer dizer aquele cara estranhamente educado que sempre pede desculpas?",
  ui_story_5079_50790700_16_dialog_content = "Ele não foi tão educado quando nos ameaçou mais cedo... Mas eu não achei que realmente chegaríamos a trocar socos depois.",
  ui_story_5079_50790700_17_dialog_content = "Ainda assim, foi bom colocar aquele estranho arrependido em seu lugar. Sinto que fiz algo semelhante antes...",
  ui_story_5079_50790700_18_dialog_content = "O que está acontecendo comigo hoje? É como se em todo lugar que eu vou, eu continuo sentindo deja vu...",
  ui_story_5079_50790700_19_dialog_content = "Posso te perguntar algo? Por que você não tentou simplesmente se explicar para eles?",
  ui_story_5079_50790700_20_dialog_content = "Claramente não somos os culpados aqui, e até a Família Ketchup tem que ouvir a razão! Por que escolher uma briga sem sentido com eles?",
  ui_story_5079_50790700_21_dialog_content = "Você disse que é sem sentido, você realmente acha que explicar as coisas teria feito alguma diferença?",
  ui_story_5079_50790700_22_dialog_content = "Eu tentei fazer isso desde que eu era uma criança... mas ninguém nunca escuta. É por isso que eu não me incomodo mais.",
  ui_story_5079_50790700_23_dialog_content = "M-Mas... Eu ouvi alguém dizer que a Família Ketchup já emitiu uma ordem para a sua prisão!",
  ui_story_5079_50790700_24_dialog_content = "Prisão?",
  ui_story_5079_50790700_25_dialog_content = "Mesmo que você parecesse totalmente legal enquanto lutava contra a Família Ketchup... Quanto mais você resistir, mais eles vão suspeitar de você.",
  ui_story_5079_50790700_26_dialog_content = "Que tal isso? Por que você não diz a eles que a Pedra da Caça só atacou porque queria te proteger, e que você na verdade não queria lutar?",
  ui_story_5079_50790700_27_dialog_content = "...",
  ui_story_5079_50790700_28_dialog_content = "É verdade que a Pedra de Caça tem vontade própria, e que meu poder vem dela...",
  ui_story_5079_50790700_29_dialog_content = "Mas tudo o que acabou de acontecer foi minha culpa. Eu não estou prestes a colocar a culpa em ninguém ou em qualquer outra coisa.",
  ui_story_5079_50790700_30_dialog_content = "!",
  ui_story_5079_50790700_31_dialog_content = "Ah... entendo. Você deve ser muito amigo de Hunting Stone. Sinceramente, estou um pouco com inveja.",
  ui_story_5079_50790700_32_dialog_content = "... Amigos? Você não poderia estar mais errado.",
  ui_story_5079_50790700_33_dialog_content = "Pode ser um pouco útil em uma luta, mas na vida cotidiana, só me traz problemas desnecessários.",
  ui_story_5079_50790700_34_dialog_content = "Quem iria querer essa coisa esquisita seguindo-os o tempo todo, ou chamá-la de \"amiga\", afinal?",
  ui_story_5079_50790700_35_dialog_content = "Uau... Isso me parece o amigo mais leal! Alguém que está sempre ao seu lado e nunca te abandona!",
  ui_story_5079_50790700_36_dialog_content = "Ok, agora estou extremamente ciumento!",
  ui_story_5079_50790700_37_dialog_content = "Você nunca ouve o que as pessoas estão te dizendo?",
  ui_story_5079_50790700_38_dialog_content = "Ele também te entende! Sempre que você estiver pronto para lutar, ele entra em ação!",
  ui_story_5079_50790700_39_dialog_content = "Se você não quer isso, por que não me deixa ficar com isso?",
  ui_story_5079_50790700_40_dialog_content = "Uh... Ou talvez não? Afinal, eu não gostaria de estragar a amizade de vocês!",
  ui_story_5079_50790700_41_dialog_content = "Se você não pode me dar, então eu poderia pegar emprestado algum dia? Por favor? Por favor?",
  ui_story_5079_50790700_42_dialog_content = "...",
  ui_story_5079_50790700_43_dialog_content = "...",
  ui_story_5079_50790700_44_dialog_content = "Você viu isso na batalha agora... Não tem medo de que possa te machucar?",
  ui_story_5079_50790700_45_dialog_content = "Uhh?",
  ui_story_5079_50790700_46_dialog_content = "Além disso, nos conhecemos há menos de um dia. Por que você está tão disposto a confiar em mim?",
  ui_story_5079_50790700_47_dialog_content = "Já ocorreu a você que estou evitando a investigação da Família Ketchup porque na verdade sou culpado?",
  ui_story_5079_50790700_48_dialog_content = "Bem... Acho que é porque estamos juntos esse tempo todo.",
  ui_story_5079_50790700_49_dialog_content = "Tenho certeza de que você é uma boa pessoa! Meu sexto sentido me diz isso!",
  ui_story_5079_50790700_50_dialog_content = "Isso não é tudo, é? Desculpe, Popo, mas você não é exatamente o melhor em esconder seus pensamentos e sentimentos.",
  ui_story_5079_50790700_51_dialog_content = "Para você confiar em mim tão incondicionalmente, significa que você já tem outro suspeito em mente, não tem?",
  ui_story_5079_50790700_52_dialog_content = "Isso é... Isso é apenas parte do motivo, mas sim!",
  ui_story_5079_50790700_53_dialog_content = "A verdade é... Eu acho que meu pai pode ser responsável por tudo isso.",
  ui_story_5079_50790700_54_dialog_content = "As cenouras foram o motivo de termos tido uma briga tão grande. Talvez ele esteja tentando me fazer gostar de cenouras, fazendo com que tudo na cidade tenha gosto delas?",
  ui_story_5079_50790700_55_dialog_content = "Mas ele realmente iria tão longe apenas para me fazer comer cenouras? Se sim, ele está indo longe demais com isso!",
  ui_story_5079_50790700_56_dialog_content = "Pare de fingir. Posso dizer pela sua expressão que você não está realmente bravo com ele.",
  ui_story_5079_50790700_57_dialog_content = "Você não odeia seu pai de forma alguma. Você está preocupado com ele - você está preocupado que ele se tornou o alvo da raiva do público.",
  ui_story_5079_50790700_58_dialog_content = "Do que você está falando? Eu não me importo com nada disso. Eu só sinto que sou parcialmente culpado pela nossa briga.",
  ui_story_5079_50790700_59_dialog_content = "Por causa do meu temperamento, eu sempre acabo irritando meu pai e deixando-o bravo...",
  ui_story_5079_50790700_60_dialog_content = "É por isso que sinto que deveria fazer algo por ele... Obviamente, isso não significa que vou me desculpar com ele ou algo assim!",
  ui_story_5079_50790700_61_dialog_content = "Um conselho: ser excessivamente teimoso só vai complicar as coisas.",
  ui_story_5079_50790700_62_dialog_content = "Hã? Mas você também é bastante teimoso, não é?",
  ui_story_5079_50790700_63_dialog_content = "Agora que penso nisso, talvez você e seu pai tenham tido um mal-entendido semelhante?",
  ui_story_5079_50790700_64_dialog_content = "Você poderia aprender uma coisa ou duas comigo, sabe! Como fazer algo bom para ele secretamente...",
  ui_story_5079_50790700_65_dialog_content = "Aposto que ele realmente iria gostar disso.",
  ui_story_5079_50790700_66_dialog_content = "Algo que ele realmente gosta, hein? Humph, acho que não consigo realizar algo assim na minha vida.",
  ui_story_5079_50790700_67_dialog_content = "Comer cenouras, se livrar da Pedra de Caça, ou se tornar a filha graciosa que ele sempre quis... Urgh, vamos parar de falar dos meus próprios assuntos.",
  ui_story_5079_50790700_68_dialog_content = "Neste momento, eu posso garantir mais ou menos... que seu pai não está por trás dessa bagunça.",
  ui_story_5079_50790700_69_dialog_content = "Hã? Sério? Então minha intuição está completamente errada? Espere, você não está apenas tentando mudar de assunto, está?",
  ui_story_5079_50790700_70_dialog_content = "Meu passado não é realmente importante mais, mas sua família é algo muito próximo e querido para você.",
  ui_story_5079_50790700_71_dialog_content = "Então, esqueça os meus problemas por agora. Quanto ao seu pai, tenho quase certeza de que descobri tudo—",
  ui_story_5079_50790700_72_dialog_content = "Se tudo agora tem gosto de cenoura, só prejudica os interesses do único comerciante de cenouras da cidade. Entendeu agora?",
  ui_story_5079_50790700_73_dialog_content = "Eu... Eu acho que sim! Hum... Se for esse o caso...",
  ui_story_5079_50790700_74_dialog_content = "Então as cenouras são completamente inúteis agora, já que as pessoas podem comer o que quiserem e ainda assim sentir o gosto delas!",
  ui_story_5079_50790700_75_dialog_content = "Bingo. Não faria sentido para o seu pai fazer algo tão prejudicial para o negócio dele.",
  ui_story_5079_50790700_76_dialog_content = "Ohhh! Isso... Isso faz todo o sentido! Você não é também um detetive, é?",
  ui_story_5079_50790700_77_dialog_content = "É apenas uma simples observação, só isso. Você também é muito bom em analisar os fatos, Popo. Algo me diz...",
  ui_story_5079_50790700_78_dialog_content = "Talvez possamos trabalhar juntos muito bem.",
  ui_story_5079_50790700_79_dialog_content = "Heeheehee, eu descobri isso há muito tempo!",
  ui_story_5079_50790700_80_dialog_content = "(É por isso que eu tenho estado tão disposto a ficar? Porque nossa maneira de pensar é tão semelhante?)",
  ui_story_5079_50790700_81_dialog_content = "(Nossas personalidades teimosas e relações com nossos pais também são bastante semelhantes...)",
  ui_story_5079_50790700_82_dialog_content = "(Poderia ser que ela é uma cópia exata de mim quando eu era uma criança? Não, isso não pode estar certo... Tenho certeza de que eu era um pouco mais maduro do que ela.)",
  ui_story_5079_50790700_83_dialog_content = "Então... Você poderia me ajudar com outra coisa?",
  ui_story_5079_50790700_84_dialog_content = "Claro! Afinal, é isso que uma pessoa madura faria... ahem, quero dizer sim, o que é?",
  ui_story_5079_50790700_85_dialog_content = "Eu... Eu acho que consigo sentir o cheiro da fonte do sabor de cenoura! Como se estivesse de alguma forma conectado a mim!",
  ui_story_5079_50790700_86_dialog_content = "Ou talvez seja porque eu odeio tanto cenouras que sou mais sensível a elas do que outras pessoas.",
  ui_story_5079_50790700_87_dialog_content = "O cheiro... Parece vir da <color=#FFB400>Floresta Creme</color>. É longe daqui, e lá tem uma caverna dedicada ao Deus da Comida.",
  ui_story_5079_50790700_88_dialog_content = "Você consegue sentir algum cheiro vindo de uma caverna na floresta a quilômetros daqui?",
  ui_story_5079_50790700_89_dialog_content = "Não! Mas meu pai costumava me levar para brincar naquela caverna o tempo todo. Se eu tiver que adivinhar, ele deve ter pegado o trem para me procurar naquela caverna!",
  ui_story_5079_50790700_90_dialog_content = "Se é lá que ele está agora, e algo assustador realmente está acontecendo na floresta...",
  ui_story_5079_50790700_91_dialog_content = "Você não precisa continuar tentando esconder. Está claro que você está realmente preocupado com seu pai.",
  ui_story_5079_50790700_92_dialog_content = "Tudo bem, eu estou preocupado! E é por isso... Eu gostaria de pegar emprestada sua Pedra de Caça e ir resgatá-lo!",
  ui_story_5079_50790700_93_dialog_content = "Acha que vai ficar bem sozinho?",
  ui_story_5079_50790700_94_dialog_content = "Hã...",
  ui_story_5079_50790700_95_dialog_content = "Admita, você está esperando que eu ofereça minha ajuda.",
  ui_story_5079_50790700_96_dialog_content = "Você é o único em quem posso confiar agora... Mas me ajudar também é bom para você!",
  ui_story_5079_50790700_97_dialog_content = "Oh? Como assim?",
  ui_story_5079_50790700_98_dialog_content = "Ajudar-me a encontrar meu pai não seria um problema para você, e uma vez que o fizermos, tenho certeza de que ele fará tudo o que puder para limpar seu bom nome.",
  ui_story_5079_50790700_99_dialog_content = "E se você conseguir eliminar o gosto de cenoura para a cidade, reunir seus ingredientes será muito mais fácil, certo?",
  ui_story_5079_50790700_100_dialog_content = "Sabia...",
  ui_story_5079_50790700_101_dialog_content = "Hã? Sabia do quê?",
  ui_story_5079_50790700_102_dialog_content = "Nada. Você apenas me impressiona às vezes, só isso.",
  ui_story_5079_50790700_103_dialog_content = "Vou te ajudar, mas não porque você me persuadiu ou algo assim. Nossos pensamentos apenas acontecem de se alinhar.",
  ui_story_5079_50790700_104_dialog_content = "Sério? Sério? Então talvez eu também tenha algum potencial de detetive em mim!",
  ui_story_5079_50790700_105_dialog_content = "É definitivamente um talento que vale a pena treinar. Talvez eu te apresente algumas das minhas regras favoritas algum dia.",
  ui_story_5079_50790700_106_dialog_content = "Regras?",
  ui_story_5079_50790700_107_dialog_content = "Interessado? Eu vou te contar tudo sobre eles quando tivermos um tempinho livre, mas agora...",
  ui_story_5079_50790700_108_dialog_content = "Vamos para a floresta!",
  ui_story_5079_50790700_109_dialog_content = "Certo! Vamos lá!",
  ui_story_5079_50790801_1_dialog_content = "Argh... O cheiro aqui fora é horrível. Definitivamente vem de um lugar...",
  ui_story_5079_50790801_2_dialog_content = "Será que é a caverna do Deus da Comida?",
  ui_story_5079_50790801_3_dialog_content = "Falando nisso, você acha que esse deus está envolvido de alguma forma?",
  ui_story_5079_50790801_4_dialog_content = "Prefiro não falar sobre isso. Afinal, o Deus da Comida é a divindade mais reverenciada de Folta.",
  ui_story_5079_50790801_5_dialog_content = "Fazemos ofertas regulares e, em troca, o Deus da Comida concede nossos desejos mais sinceros.",
  ui_story_5079_50790801_6_dialog_content = "É por isso que você suspeitou do seu pai mais cedo? Porque você acha que ele pode ter ido ao Deus da Comida e desejado que tudo tivesse gosto de cenoura?",
  ui_story_5079_50790801_7_dialog_content = "Sim...",
  ui_story_5079_50790801_8_dialog_content = "Esse Deus da Comida realmente pode fazer um desejo como esse se tornar realidade?",
  ui_story_5079_50790801_9_dialog_content = "Claro! A Família Ketchup recebeu seu sagrado Livro de Receitas Preto do Deus da Comida.",
  ui_story_5079_50790801_10_dialog_content = "Essa família está no poder há gerações, tudo graças ao conhecimento encontrado naquele livro.",
  ui_story_5079_50790801_11_dialog_content = "De repente, algo parece errado...",
  ui_story_5079_50790801_12_dialog_content = "Não me diga que tem alguém com uma mala branca cheia de ingredientes ficando perto do chefe da Família Ketchup.",
  ui_story_5079_50790801_13_dialog_content = "Eu... Eu acho que sim? Espere, isso significa que você já investigou a Família Ketchup?",
  ui_story_5079_50790801_14_dialog_content = "De forma alguma, mas algo sobre toda a Família Ketchup me faz sentir... nostálgico?",
  ui_story_5079_50790801_15_dialog_content = "Isso não é importante agora... O que importa é encontrar um caminho para chegar àquela floresta.",
  ui_story_5079_50790801_16_dialog_content = "O caminho mais rápido para a Floresta Cream é de trem, mas...",
  ui_story_5079_50790801_17_dialog_content = "Nenhum sinal deles aqui também? Homens, procurem naquela área.",
  ui_story_5079_50790801_18_dialog_content = "Sim, senhor",
  ui_story_5079_50790801_19_dialog_content = "A rua está cheia de pessoas que estão procurando por você agora mesmo...",
  ui_story_5079_50790801_20_dialog_content = "Urgh, que chato. Se minha missão não fosse tão importante, eu iria limpar o chão com aquele esquisito mais uma vez.",
  ui_story_5079_50790801_21_dialog_content = "Escute, Popo. Se eles me encontrarem e eu não conseguir evitar uma luta, você precisa pegar a Pedra da Caça e ir direto para a floresta.",
  ui_story_5079_50790801_22_dialog_content = "De jeito nenhum, eu nunca poderia te deixar para trás! Somos os parceiros perfeitos agora, lembra?",
  ui_story_5079_50790801_23_dialog_content = "Até escolhi um nome para nós! \"O Time Anti-Cenoura dos Sonhos\"!",
  ui_story_5079_50790801_24_dialog_content = "Isso é realmente o melhor que você poderia inventar? Você não poderia pelo menos tentar—",
  ui_story_5079_50790801_25_dialog_content = "<color=#828282>Vuuush!</color>",
  ui_story_5079_50790801_26_dialog_content = "Cuidado, Popo!",
  ui_story_5079_50790801_27_dialog_content = "Uhh?",
  ui_story_5079_50790801_28_dialog_content = "!",
  ui_story_5079_50790801_29_dialog_content = "Ufa... Essa foi por um triz.",
  ui_story_5079_50790801_30_dialog_content = "Agora então... Alguém pode me dizer por que um monte de frutas e vegetais estão voando pelo ar?",
  ui_story_5079_50790801_31_dialog_content = "Fique atrás da Pedra de Caça, Popo. Não chegue muito perto.",
  ui_story_5079_50790801_32_dialog_content = "T-Tudo bem... Mas o que está acontecendo ali?",
  ui_story_5079_50790801_33_dialog_content = "...",
  ui_story_5079_50790801_34_dialog_content = "Pare! O que você acha que está fazendo? Vocês são tatus ou algo assim? Por que estão tentando estragar o delicioso sabor das cenouras?",
  ui_story_5079_50790801_35_dialog_content = "Nós só queremos que tudo tenha o gosto que deveria ter!",
  ui_story_5079_50790801_36_dialog_content = "Rápido, polvilhe mais sal e bicarbonato de sódio em tudo! Quanto mais, melhor!",
  ui_story_5079_50790801_37_dialog_content = "Pare! Este deve ser o próximo passo da natureza na evolução. Não vamos deixar você interferir na vontade do Deus da Comida!",
  ui_story_5079_50790801_38_dialog_content = "Além disso, todos vocês gostam de cenouras, não é? Por que se opor a nós?",
  ui_story_5079_50790801_39_dialog_content = "Eu... Eu gosto de cenouras e tudo mais, mas eu não quero passar o resto da minha vida comendo-as!",
  ui_story_5079_50790801_40_dialog_content = "Eu sinto Muito!",
  ui_story_5079_50790801_41_dialog_content = "Pare! Pare com isso agora mesmo!",
  ui_story_5079_50790801_42_dialog_content = "Para um mundo perfeito e cheio de cenouras! Avante!",
  ui_story_5079_50790801_43_dialog_content = "Para Folta e sua orgulhosa diversidade culinária! Polvilhe!",
  ui_story_5079_50790801_44_dialog_content = "Uau... A cidade inteira enlouqueceu, não é?",
  ui_story_5079_50790801_45_dialog_content = "Tantos prédios já foram destruídos. Nesse ritmo, Folta não será mais a mesma cidade...",
  ui_story_5079_50790801_46_dialog_content = "E minha missão será praticamente um fracasso. Urgh, que dor de cabeça...",
  ui_story_5079_50790801_47_dialog_content = "Nada me incomoda mais do que esse tipo de caos e desordem.",
  ui_story_5079_50790801_48_dialog_content = "...",
  ui_story_5079_50790801_49_dialog_content = "Olha! A Pedra de Caça está se movendo!",
  ui_story_5079_50790801_50_dialog_content = "Ei! Não cause mais problemas para nós entrando na luta!",
  ui_story_5079_50790801_51_dialog_content = "Não, espera, parece que a Pedra de Caça está tentando nos levar por este caminho.",
  ui_story_5079_50790801_52_dialog_content = "... É assim mesmo?",
  ui_story_5079_50790801_53_dialog_content = "Ei, não pense que vou te seguir por aí só porque você quer que eu faça isso.",
  ui_story_5079_50790801_54_dialog_content = "...",
  ui_story_5079_50790801_55_dialog_content = "E agora você não quer que eu te alcance? Não pense que pode correr mais rápido do que eu, sua roda podre!",
  ui_story_5079_50790801_56_dialog_content = "Vamos, Popo.",
  ui_story_5079_50790801_57_dialog_content = "<size=30>Por que ela está ficando tão irritada? Acho que ela é bem imatura afinal de contas...</size>",
  ui_story_5079_50790801_58_dialog_content = "O que foi isso?",
  ui_story_5079_50790801_59_dialog_content = "Nada! Estou chegando!",
  ui_story_5079_50790801_60_dialog_content = "Você quer que a gente corte por aqui? Bem, é a estação de trem.",
  ui_story_5079_50790801_61_dialog_content = "Bem feito, Hunting Stone.",
  ui_story_5079_50790801_62_dialog_content = "!",
  ui_story_5079_50790801_63_dialog_content = "Mas não se encha muito de si mesmo. Se você acabar assustando alguém no trem novamente...",
  ui_story_5079_50790801_64_dialog_content = "Estou retirando meu elogio.",
  ui_story_5079_50790801_65_dialog_content = "Apressa-te, por favor? Eu não quero perder o trem duas vezes no mesmo dia!",
  ui_story_5079_50790801_66_dialog_content = "Ei, cuidado...",
  ui_story_5079_50790801_67_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5079_50790801_68_dialog_content = "Bem, pelo menos ela conseguiu encontrar alguém duas vezes hoje...",
  ui_story_5079_50790801_69_dialog_content = "Ai...",
  ui_story_5079_50790801_70_dialog_content = "Hã? É você, Popo?",
  ui_story_5079_50790801_71_dialog_content = "Uh-oh!",
  ui_story_5079_50790801_72_dialog_content = "Todos em Folta perderam a cabeça com esse negócio de cenoura.",
  ui_story_5079_50790801_73_dialog_content = "Como filha do único comerciante de cenouras da cidade, você deveria ser mais cuidadosa por aqui.",
  ui_story_5079_50790801_74_dialog_content = "Uh... Certo, mas...",
  ui_story_5079_50790801_75_dialog_content = "Aqui, vou acompanhá-lo de volta.",
  ui_story_5079_50790801_76_dialog_content = "M-Mas eu tenho que pegar o trem.",
  ui_story_5079_50790801_77_dialog_content = "O trem? Você quer dizer o que está indo para a Floresta Cream? Espere um minuto...",
  ui_story_5079_50790801_78_dialog_content = "Quem é essa pessoa ao seu lado? Espere, essa roda... Eu já ouvi falar dela antes! Será que ela poderia ser...",
  ui_story_5079_50790801_79_dialog_content = "Poupe-nos das teatralidades já. Sim, sou eu - o intruso malvado de fora da cidade. Feliz agora?",
  ui_story_5079_50790801_80_dialog_content = "Vá em frente e embarque no trem, Popo. Eu vou pegar as coisas daqui.",
  ui_story_5079_50790901_1_dialog_content = "E-Espere, parem! Vocês dois!",
  ui_story_5079_50790901_2_dialog_content = "...",
  ui_story_5079_50790901_3_dialog_content = "...",
  ui_story_5079_50790901_4_dialog_content = "Eu te conheço! Você é um dos nossos clientes regulares, não é?",
  ui_story_5079_50790901_5_dialog_content = "Você ama cenouras, é por isso que está lutando para manter as coisas como estão agora! Certo? Certo?",
  ui_story_5079_50790901_6_dialog_content = "Sim... Eu sabia que a filha do nosso grande comerciante de cenouras entenderia.",
  ui_story_5079_50790901_7_dialog_content = "Então não há motivo para lutarmos! Você sabe por que a Família Ketchup está atrás do meu amigo aqui, certo?",
  ui_story_5079_50790901_8_dialog_content = "... Isso significa que os rumores são verdadeiros?",
  ui_story_5079_50790901_9_dialog_content = "Não exatamente, não. Ela é uma detetive e está me ajudando a procurar meu pai agora mesmo.",
  ui_story_5079_50790901_10_dialog_content = "Aham... Pactlock Holmes, ao seu serviço.",
  ui_story_5079_50790901_11_dialog_content = "Entendi, entendi. Seja você um detetive de verdade ou não, nós lhe devemos nossa gratidão!",
  ui_story_5079_50790901_12_dialog_content = "Na verdade, ficaríamos honrados se você servisse como a Santinha das Cenouras de nossa organização!",
  ui_story_5079_50790901_13_dialog_content = "Não, obrigado, mas se você realmente quer expressar sua gratidão...",
  ui_story_5079_50790901_14_dialog_content = "Preciso pegar aquele trem, mas não tenho certeza de como está a estação agora. Acha que pode me dar cobertura?",
  ui_story_5079_50790901_15_dialog_content = "Claro! Se eu não estou enganado, a pessoa que vende passagens de trem pertence à facção inimiga.",
  ui_story_5079_50790901_16_dialog_content = "Vou garantir que nenhum deles consiga ver você!",
  ui_story_5079_50790901_17_dialog_content = "Lá, agora é a sua chance! Meu povo chamou a atenção dele, e uma luta deve começar em breve...",
  ui_story_5079_50790901_18_dialog_content = "Vá para a estação o mais rápido que puder!",
  ui_story_5079_50790901_19_dialog_content = "Obrigado... Mas por que você e seu povo estão dispostos a ir tão longe apenas por causa de cenouras?",
  ui_story_5079_50790901_20_dialog_content = "Naturalmente, é porque não conseguimos nem começar a descrever nosso amor por cenouras!",
  ui_story_5079_50790901_21_dialog_content = "Crocantes e doces, eles têm uma textura maravilhosa. Você poderia comer uma centena de cenouras sem se cansar delas!",
  ui_story_5079_50790901_22_dialog_content = "Eles também são uma excelente fonte de energia e nutrição! Eles podem promover o crescimento e desenvolvimento ósseo, melhorar a tez e até aliviar a fadiga ocular!",
  ui_story_5079_50790901_23_dialog_content = "Mas o mais importante, esses magníficos vegetais podem tratar a constipação! Aqueles que odeiam cenouras devem estar tão conflituosos sobre isso agora!",
  ui_story_5079_50790901_24_dialog_content = "... E-é isso?",
  ui_story_5079_50790901_25_dialog_content = "<size=30>Eu não fazia ideia de que as cenouras tinham tantas qualidades boas.</size>",
  ui_story_5079_50790901_26_dialog_content = "Mas por que você pergunta, Santinha Cenoura? A menos que... Ah, eu entendi!",
  ui_story_5079_50790901_27_dialog_content = "Você estava testando minha devoção à poderosa cenoura agora, não estava? Fique tranquila, minha santinha, eu sempre estarei do lado da bondade da cenoura!",
  ui_story_5079_50790901_28_dialog_content = "Uh... Ok então. Eu respeito a sua decisão.",
  ui_story_5079_50790901_29_dialog_content = "Devemos ir, Popo.",
  ui_story_5079_50790901_30_dialog_content = "Só um momento. Você também vai com ela, Popo?",
  ui_story_5079_50790901_31_dialog_content = "Sim, claro. Isso é um problema?",
  ui_story_5079_50790901_32_dialog_content = "Nossos inimigos podem ter olhos fora da cidade. Eles podem não reconhecer a Santinha da Cenoura, mas com certeza vão reconhecer você.",
  ui_story_5079_50790901_33_dialog_content = "Seria perigoso para você ir sozinho!",
  ui_story_5079_50790901_34_dialog_content = "É verdade... Pode ser melhor para você ficar aqui, Popo. Tenho certeza de que os clientes regulares da sua loja cuidarão bem de você.",
  ui_story_5079_50790901_35_dialog_content = "Mas... Mas eu quero te ajudar—",
  ui_story_5079_50790901_36_dialog_content = "Fique tranquilo, meu povo e eu faremos tudo ao nosso alcance para proteger a Princesa Popo.",
  ui_story_5079_50790901_37_dialog_content = "P-Princesa?",
  ui_story_5079_50790901_38_dialog_content = "Você vai ficar bem, Popo. Lembra quando você queria pegar a Pedra da Caça emprestada antes?",
  ui_story_5079_50790901_39_dialog_content = "Como ele gosta tanto de você, tenho certeza de que não se importará em ficar ao seu lado. Assim, você não terá nada com que se preocupar, certo?",
  ui_story_5079_50790901_40_dialog_content = "Mas então... Isso não tornará as coisas mais perigosas para você?",
  ui_story_5079_50790901_41_dialog_content = "Eu? Você está brincando? Eu me sentiria muito melhor sem a Pedra de Caça me seguindo por aí.",
  ui_story_5079_50790901_42_dialog_content = "Além disso, vocês são amigos agora, certo? Você até consegue entender os sentimentos dele.",
  ui_story_5079_50790901_43_dialog_content = "E parece que realmente quer ficar com você...",
  ui_story_5079_50790901_44_dialog_content = "?",
  ui_story_5079_50790901_45_dialog_content = "Se fosse qualquer outra pessoa, voltaria para mim imediatamente.",
  ui_story_5079_50790901_46_dialog_content = "Isso significa... que eu sou especial?",
  ui_story_5079_50790901_47_dialog_content = "Parece que sim. Então apenas fique aqui e me espere, ok?",
  ui_story_5079_50790901_48_dialog_content = "O-Ok... Vou fazer exatamente como você pediu! Não é mesmo, Hunting Stone?",
  ui_story_5079_50790901_49_dialog_content = "!",
  ui_story_5079_50790901_50_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50790901_51_dialog_content = "Peço a atenção de todos, por favor! É uma honra para mim apresentar a todos vocês a Princesa Popo, filha do nosso venerável comerciante de cenouras da cidade!",
  ui_story_5079_50790901_52_dialog_content = "Bem-vindo!",
  ui_story_5079_50790901_53_dialog_content = "O-Olá, pessoal.",
  ui_story_5079_50790901_54_dialog_content = "Para fazer você se sentir mais em casa, preparei um bolo muito especial só para você! Por favor, aproveite, Princesa Popo!",
  ui_story_5079_50790901_55_dialog_content = "Por favor, aproveite!",
  ui_story_5079_50790901_56_dialog_content = "Gastei meu sangue, suor e lágrimas assando este bolo para você! Eu até adicionei cenouras amassadas ao creme...",
  ui_story_5079_50790901_57_dialog_content = "Naturalmente, eu só usei as cenouras mais frescas e de melhor qualidade da loja do seu pai!",
  ui_story_5079_50790901_58_dialog_content = "Embora pareça um pouco redundante fazer um bolo de cenoura para a filha de um comerciante de cenouras, espero que você goste mesmo assim.",
  ui_story_5079_50790901_59_dialog_content = "Nós também esperamos!",
  ui_story_5079_50790901_60_dialog_content = "Bom...",
  ui_story_5079_50790901_61_dialog_content = "Por favor, aproveite, princesa.",
  ui_story_5079_50790901_62_dialog_content = "P-Posso comer em um lugar tranquilo e agradável? Não estou acostumado a comer na frente de tanta gente...",
  ui_story_5079_50790901_63_dialog_content = "Claro, princesa! Mas se eu posso perguntar, por que você parece tão enjoada?",
  ui_story_5079_50790901_64_dialog_content = "Será que o meu bolo de cenoura não está à altura dos seus padrões?",
  ui_story_5079_50790901_65_dialog_content = "Não, não é isso...",
  ui_story_5079_50790901_66_dialog_content = "Agora que penso nisso, alguém já viu a filha do comerciante de cenouras comer uma cenoura antes?",
  ui_story_5079_50790901_67_dialog_content = "Não, mas eu a vi discutir com o pai uma vez, e parecia que as cenouras eram o motivo da briga deles...",
  ui_story_5079_50790901_68_dialog_content = "?",
  ui_story_5079_50790901_69_dialog_content = "Eu... Eu amo cenouras! Você só não me viu comendo, só isso... V-Viu? El-Elas são deliciosas...",
  ui_story_5079_50790901_70_dialog_content = "Urgh... Blegh...",
  ui_story_5079_50790901_71_dialog_content = "Você está realmente beliscando seu nariz agora?",
  ui_story_5079_50790901_72_dialog_content = "V-Você não entende! Esta é a melhor maneira de experimentar o sabor das cenouras—",
  ui_story_5079_50790901_73_dialog_content = "<size=45>Pffffft—</size>",
  ui_story_5079_50790901_74_dialog_content = "...",
  ui_story_5079_50790901_75_dialog_content = "...",
  ui_story_5079_50790901_76_dialog_content = "...",
  ui_story_5079_50790901_77_dialog_content = "Você não gosta de cenouras mesmo, não é? Você não é nossa princesa, mas nossa inimiga jurada!",
  ui_story_5079_50790901_78_dialog_content = "Seu amigo foi para a Floresta Cream para procurar seu pai, certo?",
  ui_story_5079_50790901_79_dialog_content = "O que ela poderia estar fazendo lá fora? Será que ela está tentando destruir nosso belo paraíso, cheio de cenouras?",
  ui_story_5079_50790901_80_dialog_content = "Rápido! Temos que capturar a Popo e forçá-la a nos levar até aquela mulher!",
  ui_story_5079_50790901_81_dialog_content = "Não... N-Não chegue mais perto!",
  ui_story_5079_50790901_82_dialog_content = "Você vai me ajudar, não vai? Pedra de Caça?",
  ui_story_5079_50790901_83_dialog_content = "!",
  ui_story_5079_50791001_1_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50791001_2_dialog_content = "Um prazer encontrá-la novamente, minha senhora. Chegamos na Floresta Cream, por favor, preste atenção onde pisa ao sair do trem.",
  ui_story_5079_50791001_3_dialog_content = "Ah... Já estamos aqui? Isso foi muito mais rápido do que eu esperava...",
  ui_story_5079_50791001_4_dialog_content = "As coisas são quase estranhamente chatas sem uma criança irritante ou uma roda pegajosa por perto.",
  ui_story_5079_50791001_5_dialog_content = "Na verdade, foi uma viagem bastante longa, embora você tenha passado a maior parte do tempo olhando pela janela.",
  ui_story_5079_50791001_6_dialog_content = "A agitação em Folta é a fonte do seu estresse? Posso ser de alguma ajuda?",
  ui_story_5079_50791001_7_dialog_content = "Então você está ciente do que está acontecendo na cidade?",
  ui_story_5079_50791001_8_dialog_content = "Não se preocupe com isso, tenho algo mais importante para perguntar. Você viu o dono da loja de cenouras recentemente?",
  ui_story_5079_50791001_9_dialog_content = "Pelo que ouvi, ele saiu da cidade neste trem mais cedo hoje.",
  ui_story_5079_50791001_10_dialog_content = "O comerciante de cenouras? Sim, na verdade. Ele desceu nesta mesma estação, e acredito que mencionou ir para a caverna do Deus da Comida.",
  ui_story_5079_50791001_11_dialog_content = "Sério? Parece que Popo estava certo o tempo todo.",
  ui_story_5079_50791001_12_dialog_content = "Acredito que você também tem uma impressão dele.",
  ui_story_5079_50791001_13_dialog_content = "Afinal, você o conheceu quando chegou pela primeira vez em Folta. Foi um encontro bastante divertido, devo dizer.",
  ui_story_5079_50791001_14_dialog_content = "Eu o conheci? Você quer dizer que aquele passageiro extremamente modesto era o pai do Popo?",
  ui_story_5079_50791001_15_dialog_content = "Urgh, toda essa confusão poderia ter sido evitada se eu tivesse apenas impedido ele de embarcar no trem naquela época...",
  ui_story_5079_50791001_16_dialog_content = "Parece que sua pergunta foi respondida. Por favor, lembre-se de pegar sua bagagem ao sair do trem... Er, só um momento.",
  ui_story_5079_50791001_17_dialog_content = "Desculpe-me, mas você finalmente se livrou da Pedra de Caça?",
  ui_story_5079_50791001_18_dialog_content = "Certamente você não o abandonou em um canto escuro da cidade e o deixou sofrer em uma solidão miserável, não é?",
  ui_story_5079_50791001_19_dialog_content = "Você não precisa fazer isso parecer tão miserável...",
  ui_story_5079_50791001_20_dialog_content = "Acabei de deixá-lo com outra pessoa por enquanto.",
  ui_story_5079_50791001_21_dialog_content = "Perdoe-me, não pude evitar de imaginar uma cena de imensa tragédia e solidão agora mesmo.",
  ui_story_5079_50791001_22_dialog_content = "Acredito que o lugar de direito dele é ao seu lado, e o mesmo vale para você também.",
  ui_story_5079_50791001_23_dialog_content = "Eu realmente não preciso da sua opinião sobre nosso relacionamento... Mas obrigado pela informação.",
  ui_story_5079_50791001_24_dialog_content = "Não pense nisso. Estou encantado em ajudá-lo.",
  ui_story_5079_50791001_25_dialog_content = "Falando nisso, o chefe da Família Ketchup tentou entrar em contato com você sobre o pai do Popo também.",
  ui_story_5079_50791001_26_dialog_content = "Mas você se recusou a responder a ela... A princípio, pensei que você fosse uma pessoa insensível, mas descobri que você é realmente muito gentil.",
  ui_story_5079_50791001_27_dialog_content = "Se o pedido fosse seu, meu querido passageiro, eu teria ido a qualquer extremo para ajudá-lo.",
  ui_story_5079_50791001_28_dialog_content = "Mas eu me recuso a lidar com aquela mulher louca de qualquer maneira. Eu preferiria passar toda a eternidade em solidão fria do que me reconectar com ela!",
  ui_story_5079_50791001_29_dialog_content = "E-eu entendo, desculpe se te chateei. Vou sair do trem imediatamente.",
  ui_story_5079_50791001_30_dialog_content = "O cheiro de cenouras está ficando cada vez mais forte...",
  ui_story_5079_50791001_31_dialog_content = "A origem do problema deve estar por aqui em algum lugar.",
  ui_story_5079_50791001_32_dialog_content = "Graaah!",
  ui_story_5079_50791001_33_dialog_content = "O-O quê?",
  ui_story_5079_50791001_34_dialog_content = "O que os Eclipsitas estão fazendo em um lugar como este?",
  ui_story_5079_50791001_35_dialog_content = "Eu sabia que havia algo estranho neste cheiro de cenoura... O poder do Deus da Comida está de alguma forma conectado aos Eclipsitas?",
  ui_story_5079_50791001_36_dialog_content = "Se for assim, Folta está em muito mais perigo do que percebemos.",
  ui_story_5079_50791001_37_dialog_content = "Preciso evitar eles por agora e verificar a caverna...",
  ui_story_5079_50791001_38_dialog_content = "Graaah!",
  ui_story_5079_50791001_39_dialog_content = "Tsk, quanto mais me aproximo da caverna, mais Eclipsitas aparecem.",
  ui_story_5079_50791001_40_dialog_content = "Tudo bem, Pedra de Caça, vamos...",
  ui_story_5079_50791001_41_dialog_content = "Não, espera, a Pedra de Caça não está comigo agora... Será que consigo lidar com tantos Eclipsitas sozinho?",
  ui_story_5079_50791001_42_dialog_content = "... Ei.",
  ui_story_5079_50791001_43_dialog_content = "Qual é o problema, Pact? Quando você ficou tão fraco?",
  ui_story_5079_50791001_44_dialog_content = "Sem a Pedra de Caça, eliminar esses Eclipsitas deve ser muito mais fácil!",
  ui_story_5079_50791001_45_dialog_content = "Venha nos pegar... Quer dizer, a mim! Venha me pegar!",
  ui_story_5079_50791001_46_dialog_content = "<color=#e8d9bb>Que droga!</color>",
  ui_story_5079_50791001_47_dialog_content = "...",
  ui_story_5079_50791001_48_dialog_content = "Graaah!",
  ui_story_5079_50791001_49_dialog_content = "... Ligar!",
  ui_story_5079_50791001_50_dialog_content = "Graaah!",
  ui_story_5079_50791001_51_dialog_content = "Tsc... Meus ataques foram muito mais lentos, e eles se libertaram das minhas amarras muito antes do que eu esperava.",
  ui_story_5079_50791001_52_dialog_content = "Eu não teria tantos problemas contra esses Eclipsitas ridiculamente fracos se eu tivesse Hunting Stone comigo...",
  ui_story_5079_50791001_53_dialog_content = "Isso não pode estar acontecendo... Eu estou realmente começando a sentir falta daquela roda estúpida! Eu sou uma piada...",
  ui_story_5079_50791001_54_dialog_content = "Eu deveria confiar na minha própria força agora...",
  ui_story_5079_50791100_1_dialog_content = "Graah—",
  ui_story_5079_50791100_2_dialog_content = "Ufa... Esse deve ser o último deles.",
  ui_story_5079_50791100_3_dialog_content = "Viu? Meus Luminatics ainda são fortes o suficiente para derrubar tantos Eclipsitas <color=#FFB400>sozinho</color>.",
  ui_story_5079_50791100_4_dialog_content = "Embora no passado, isso não me desgastasse tanto.",
  ui_story_5079_50791100_5_dialog_content = "Pedra de Caça... Eu não preciso dela para lutar, mas ela tem algumas utilidades...",
  ui_story_5079_50791100_6_dialog_content = "Graaah!",
  ui_story_5079_50791100_7_dialog_content = "Ah!",
  ui_story_5079_50791100_8_dialog_content = "Baixei minha guarda! Eu tenho que—",
  ui_story_5079_50791100_9_dialog_content = "!",
  ui_story_5079_50791100_10_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5079_50791100_11_dialog_content = "Pedra de Caça? Quem te disse para voltar para mim? Não me diga que você—",
  ui_story_5079_50791100_12_dialog_content = "Ei! Você está bem?",
  ui_story_5079_50791100_13_dialog_content = "Popo? Heh, claro que estou bem. Só me dê um segundo para limpar o resto desses Eclipsitas.",
  ui_story_5079_50791100_14_dialog_content = "Prove do sabor dos meus belos espinhos!",
  ui_story_5079_50791100_15_dialog_content = "<color=#e8d9bb>Banco! Smack!</color>",
  ui_story_5079_50791100_16_dialog_content = "Graaah!",
  ui_story_5079_50791100_17_dialog_content = "Eu também posso ajudar! Pedra de Caça!",
  ui_story_5079_50791100_18_dialog_content = "!",
  ui_story_5079_50791100_19_dialog_content = "Graaah...",
  ui_story_5079_50791100_20_dialog_content = "Conseguimos! Conseguimos! Eliminamos todos esses Eclipsitas desagradáveis juntos!",
  ui_story_5079_50791100_21_dialog_content = "Isso mesmo, nós fizemos! Você foi incrível, Popo. Eu não tinha ideia de que você poderia usar Luminatics!",
  ui_story_5079_50791100_22_dialog_content = "Isso é porque eu não conseguia... pelo menos não antes.",
  ui_story_5079_50791100_23_dialog_content = "Mas eu fiquei tão assustado quando vi esses Eclipsitas atacando você, e de repente esse poder surgiu dentro de mim!",
  ui_story_5079_50791100_24_dialog_content = "Honestamente, não consigo acreditar. Aposto que meu pai ficará tão feliz quando descobrir!",
  ui_story_5079_50791100_25_dialog_content = "S-Sim... Definitivamente...",
  ui_story_5079_50791100_26_dialog_content = "(A fonte do poder de Popo é a mesma que a minha, e ela parece ter muito potencial...)",
  ui_story_5079_50791100_27_dialog_content = "(É por isso que ela conseguiu comandar a Pedra de Caça? Eu pensei que era para obedecer apenas a mim...)",
  ui_story_5079_50791100_28_dialog_content = "O cheiro de cenouras vem da caverna do Deus da Comida! Tenho certeza disso agora!",
  ui_story_5079_50791100_29_dialog_content = "Eu também ouço uma voz... Está me dizendo para me aproximar!",
  ui_story_5079_50791100_30_dialog_content = "Uma voz? Acho que você está apenas ansioso para encontrar seu pai...",
  ui_story_5079_50791100_31_dialog_content = "Acho que isso significa que você se importa muito mais com ele do que deixa transparecer...",
  ui_story_5079_50791100_32_dialog_content = "De qualquer forma, não te pedi para me esperar na cidade? O que te fez vir atrás de mim?",
  ui_story_5079_50791100_33_dialog_content = "Sobre isso... Aqueles loucos amantes de cenoura me forçaram a comer o bolo de cenoura deles, e eu acabei cuspindo. Foi quando eu soube que minha cobertura foi descoberta.",
  ui_story_5079_50791100_34_dialog_content = "Então eu fugi com a Pedra de Caça, mas não percebi que era ainda mais rápido que um trem. Chegamos aqui em quase nenhum tempo... Você não está bravo comigo, está?",
  ui_story_5079_50791100_35_dialog_content = "Claro que não. Se alguma coisa, estou furioso que esses adultos tentaram te punir com algo tão nojento!",
  ui_story_5079_50791100_36_dialog_content = "Certo? Certo? Eu não consegui engolir uma única mordida! É por isso que eu não tive escolha a não ser vir te encontrar.",
  ui_story_5079_50791100_37_dialog_content = "Eu sabia disso o tempo todo - a Equipe Anti-Cenoura dos Sonhos tem que ficar unida, não importa o quê!",
  ui_story_5079_50791100_38_dialog_content = "<size=30>Mas só existe uma Pedra de Caça...</size>",
  ui_story_5079_50791100_39_dialog_content = "Uhh?",
  ui_story_5079_50791100_40_dialog_content = "(Popo provavelmente ainda não percebeu. Seus Luminatics ainda são muito fracos, então ela tem que confiar na Pedra de Caça para usá-los...)",
  ui_story_5079_50791100_41_dialog_content = "Qual é o grande problema, Pedra de Caça? Normalmente, nunca consigo me livrar de você, mas você parece bastante apegado ao seu novo mestre agora...",
  ui_story_5079_50791100_42_dialog_content = "Já que você a escolheu em vez de mim, é melhor cuidar bem dela. Entendeu?",
  ui_story_5079_50791100_43_dialog_content = "Você não precisa mais me seguir por aí, então me deixe finalmente desfrutar de um pouco de paz e sossego.",
  ui_story_5079_50791100_44_dialog_content = "...",
  ui_story_5079_50791100_45_dialog_content = "O que você está sussurrando ali?",
  ui_story_5079_50791100_46_dialog_content = "Como membro da equipe, eu exijo saber!",
  ui_story_5079_50791100_47_dialog_content = "Não se preocupe com isso. Além disso, tenho melhores notícias para compartilhar com você. Eu falei com o condutor do trem, e ele disse que seu pai desceu do trem aqui.",
  ui_story_5079_50791100_48_dialog_content = "Ele está definitivamente envolvido neste incidente louco, embora eu não tenha certeza exatamente de como.",
  ui_story_5079_50791100_49_dialog_content = "Será que o pai realmente...",
  ui_story_5079_50791100_50_dialog_content = "Vou entrar na floresta e verificar as coisas. Você e a Pedra da Caça podem ficar de vigia aqui fora.",
  ui_story_5079_50791100_51_dialog_content = "Isso não vai acontecer! Se você está indo para a floresta, então eu também vou!",
  ui_story_5079_50791100_52_dialog_content = "Há Eclipsitas à espreita por aqui, e haverá ainda mais deles na floresta. Permitir que você venha seria muito perigoso.",
  ui_story_5079_50791100_53_dialog_content = "Mas eu posso usar Luminatics agora! Eu posso ajudar!",
  ui_story_5079_50791100_54_dialog_content = "Você acabou de descobrir seus poderes hoje, não foi? Usá-los para se proteger vai exigir tudo o que você tem, e eu não terei tempo para vir ao seu resgate...",
  ui_story_5079_50791100_55_dialog_content = "Eu posso me virar muito bem. Supostamente, deveríamos estar ajudando uns aos outros, como combinamos!",
  ui_story_5079_50791100_56_dialog_content = "Além disso, eu não acabei de te salvar de um monte de Eclipsitas agora mesmo?",
  ui_story_5079_50791100_57_dialog_content = "...",
  ui_story_5079_50791100_58_dialog_content = "(Tudo que eu conseguia pensar antes era em me livrar da Pedra de Caça, mas depois de ver o quão próxima ela se tornou de Popo, eu...)",
  ui_story_5079_50791100_59_dialog_content = "Apenas diga, você não confia em mim de jeito nenhum, não é?",
  ui_story_5079_50791100_60_dialog_content = "Não é que eu não confie em você. Só estou preocupado que seu pai fique desapontado se ele ver seu Luminatics mal desenvolvido em ação.",
  ui_story_5079_50791100_61_dialog_content = "C-Como? De jeito nenhum... Pai sempre sonhou que eu aprenderia a usar Luminatics algum dia!",
  ui_story_5079_50791100_62_dialog_content = "Sério? Mas se você aprender Luminatics, as expectativas dele só vão aumentar cada vez mais. Ele não vai parar até que você se torne a filha ideal dele...",
  ui_story_5079_50791100_63_dialog_content = "Mas quem sabe quando ele ficará satisfeito? Na verdade, ele pode até mesmo...",
  ui_story_5079_50791100_64_dialog_content = "...",
  ui_story_5079_50791100_65_dialog_content = "Uh, não é nada. Esqueça que eu disse qualquer coisa...",
  ui_story_5079_50791100_66_dialog_content = "Eu... Eu não estou tão animado para mostrar a ele meus Luminatics...",
  ui_story_5079_50791100_67_dialog_content = "Não importa para mim, contanto que eu saiba que ele está seguro. Ajudar você com sua missão é muito mais importante.",
  ui_story_5079_50791100_68_dialog_content = "Além disso, chegaremos lá mais rápido se eu liderar o caminho. Confie em mim, eu conheço muitos atalhos!",
  ui_story_5079_50791100_69_dialog_content = "Atalhos? <size=30>Pedra de Caça, certifique-se de que não há Eclipsitas no caminho do Popo.</size>",
  ui_story_5079_50791100_70_dialog_content = "...",
  ui_story_5079_50791100_71_dialog_content = "Tsk, ele foi protegê-la sem qualquer hesitação...",
  ui_story_5079_50791100_72_dialog_content = "Bem, pelo menos é bom e tranquilo caminhar sozinho.",
  ui_story_5079_50791100_73_dialog_content = "Contanto que me ajude a completar minha missão... Acho que posso aguentar por enquanto.",
  ui_story_5079_50791100_74_dialog_content = "Minha senhora, a base daqueles fanáticos por cenouras no oeste de Folta está sob nosso controle agora.",
  ui_story_5079_50791100_75_dialog_content = "Embora tenha exigido muita persuasão, os odiadores de cenoura do lado leste da cidade também concordaram em parar de fazer tumulto.",
  ui_story_5079_50791100_76_dialog_content = "A paz de Folta foi restaurada, embora temporariamente. No entanto...",
  ui_story_5079_50791100_77_dialog_content = "O forasteiro e Popo ainda não foram capturados, certo?",
  ui_story_5079_50791100_78_dialog_content = "Minha própria inadequação é a culpada... Por favor, me perdoe...",
  ui_story_5079_50791100_79_dialog_content = "Não, isso não tem nada a ver com você. Esses eventos foram previstos há muito tempo pelo Livro de Receitas Negro...",
  ui_story_5079_50791100_80_dialog_content = "\"Aqueles que detestam isso devem nutri-lo. Ao fazer isso, eles também acabarão com isso.\"",
  ui_story_5079_50791100_81_dialog_content = "Perdoe minha ignorância, mas o que exatamente essa profecia—",
  ui_story_5079_50791100_82_dialog_content = "Isso significa que aqueles que mais desprezam as cenouras são responsáveis por esse desastre, e também são eles que vão acabar com isso.",
  ui_story_5079_50791100_83_dialog_content = "Eles são claramente duas pessoas, mas também são uma e a mesma... Que profecia interessante.",
  ui_story_5079_50791100_84_dialog_content = "Eles foram em direção à caverna do Deus da Comida, não foram?",
  ui_story_5079_50791100_85_dialog_content = "Sim, minha senhora. Devemos ir atrás deles?",
  ui_story_5079_50791100_86_dialog_content = "Heheh, receio que não. Este sonho não nos pertence, o que significa que não temos o direito de interferir.",
  ui_story_5079_50791100_87_dialog_content = "Me diga, você gosta de contos de fadas?",
  ui_story_5079_50791100_88_dialog_content = "Contos de fadas? Se for o seu desejo, eu sempre posso ler mais deles...",
  ui_story_5079_50791100_89_dialog_content = "Um mundo bonito sempre esconde a verdade cruel e brutal.",
  ui_story_5079_50791100_90_dialog_content = "Mas confrontar essa crueldade e emergir dela é caminhar em direção à luz.",
  ui_story_5079_50791100_91_dialog_content = "Este ciclo de contradições é o caminho que leva à Verdade.",
  ui_story_5079_50791100_92_dialog_content = "Sim, eu sei.",
  ui_story_5079_50791100_93_dialog_content = "Onde o trem está estacionado agora?",
  ui_story_5079_50791100_94_dialog_content = "O trem? Ele já foi fundo na Floresta Cream, e temo que não retornará a Folta tão cedo.",
  ui_story_5079_50791100_95_dialog_content = "É mesmo? Se eu soubesse antes, teria dado uma volta nele também.",
  ui_story_5079_50791100_96_dialog_content = "Embora ele não tenha intenção de relembrar os velhos tempos comigo, não se sabe quando teremos outra oportunidade como esta...",
  ui_story_5079_50791100_97_dialog_content = "Sua disputa com o condutor remonta ainda mais do que a minha própria vida...",
  ui_story_5079_50791100_98_dialog_content = "Não, eu não tenho o direito de perguntar sobre essas coisas... Por favor, me perdoe...",
  ui_story_5079_50791200_1_dialog_content = "<color=#e8d9bb>*passos*</color>",
  ui_story_5079_50791200_2_dialog_content = "Seus passos estão ficando mais pesados. Você precisa de uma pausa?",
  ui_story_5079_50791200_3_dialog_content = "Eu... estou bem.",
  ui_story_5079_50791200_4_dialog_content = "Se você está bem, então não belisque seu nariz quando me responder...",
  ui_story_5079_50791200_5_dialog_content = "De qualquer forma, você realmente parece conhecer bem este lugar. Até conseguimos evitar algumas turbas de Eclipsitas. Estamos quase lá?",
  ui_story_5079_50791200_6_dialog_content = "Claro... Claro que eu conheço bem este lugar... Afinal, é a minha base secreta.",
  ui_story_5079_50791200_7_dialog_content = "Foi aqui que eu ofereci ao Deus da Comida todas as cenouras nojentas que eu não queria comer...",
  ui_story_5079_50791200_8_dialog_content = "Naturalmente, eu tive que... limpar muitos caminhos...",
  ui_story_5079_50791200_9_dialog_content = "Você não estava preocupado que o Deus da Comida iria te punir por oferecer apenas as coisas que você não queria comer?",
  ui_story_5079_50791200_10_dialog_content = "De jeito nenhum! Minhas ofertas foram totalmente sinceras...",
  ui_story_5079_50791200_11_dialog_content = "Eu rezei sinceramente ao Deus da Comida... para deletar as cenouras de todas as receitas do mundo!",
  ui_story_5079_50791200_12_dialog_content = "Você deve ser bastante sincero já que grita assim mesmo estando tão fraco...",
  ui_story_5079_50791200_13_dialog_content = "Sabe de uma coisa? Acho que fiz algo semelhante quando era criança...",
  ui_story_5079_50791200_14_dialog_content = "Infelizmente, não me fez muito bem. É melhor você economizar sua força—",
  ui_story_5079_50791200_15_dialog_content = "Hah... Estamos aqui - a caverna do Deus da Comida!",
  ui_story_5079_50791200_16_dialog_content = "*tosse* Eu acho... que posso ser... alérgico a cenouras...",
  ui_story_5079_50791200_17_dialog_content = "Tenho certeza de que isso não é apenas por causa das cenouras...",
  ui_story_5079_50791200_18_dialog_content = "Com tantos Eclipsitas reunidos aqui, o Fluxo Escuro está especialmente denso. É normal que você se sinta afetado por isso.",
  ui_story_5079_50791200_19_dialog_content = "Felizmente, a caverna não parece muito profunda. Eu vou entrar e dar uma olhada enquanto você recupera o fôlego na entrada da caverna.",
  ui_story_5079_50791200_20_dialog_content = "Pedra de Caça, fique aqui e proteja Popo.",
  ui_story_5079_50791200_21_dialog_content = "...",
  ui_story_5079_50791200_22_dialog_content = "Qual é? Eu pensei que vocês dois eram melhores amigos, então por que você está se preocupando comigo de novo?",
  ui_story_5079_50791200_23_dialog_content = "...",
  ui_story_5079_50791200_24_dialog_content = "Pedra de Caça... Eu-Eu acho que você deveria ir com ela.",
  ui_story_5079_50791200_25_dialog_content = "Popo! Agora não é hora de bancar o valente!",
  ui_story_5079_50791200_26_dialog_content = "E-Eu não estou! Na minha condição atual, eu não consigo controlar a Pedra de Caça... Deixá-la comigo seria inútil.",
  ui_story_5079_50791200_27_dialog_content = "Não se preocupe, eu conheço este lugar como a palma da minha mão. Levaria cem anos para os Eclipsitas me encontrarem em um dos meus esconderijos! Heehee...",
  ui_story_5079_50791200_28_dialog_content = "... Eu entendi o que você está dizendo agora. Você quer que eu use a Pedra da Caça para proteger seu pai se ele realmente estiver lá, não é?",
  ui_story_5079_50791200_29_dialog_content = "Não se preocupe, não vou deixar nada acontecer com ele.",
  ui_story_5079_50791200_30_dialog_content = "Não foi isso que eu quis dizer agora... Mas...",
  ui_story_5079_50791200_31_dialog_content = "Por favor... Apenas volte em segurança, tanto você quanto meu pai...",
  ui_story_5079_50791200_32_dialog_content = "Há aquela sensação de novo... Por que essa caverna parece tão familiar?",
  ui_story_5079_50791200_33_dialog_content = "É como quando conheci a chefe da Família Ketchup e seu conselheiro. Mas esse sentimento...",
  ui_story_5079_50791200_34_dialog_content = "É tão triste e doloroso...",
  ui_story_5079_50791200_35_dialog_content = "!",
  ui_story_5079_50791200_36_dialog_content = "Eu... Eu estive aqui antes, mas a última vez... Foi porque eu estava fugindo?",
  ui_story_5079_50791200_37_dialog_content = "...",
  ui_story_5079_50791200_38_dialog_content = "...",
  ui_story_5079_50791200_39_dialog_content = "*soluçando* Se ao menos...",
  ui_story_5079_50791200_40_dialog_content = "Se eu tivesse conhecido Luminatics mais cedo, então talvez...",
  ui_story_5079_50791200_41_dialog_content = "Talvez a mãe não tivesse sido morta pelos Eclipsitas...",
  ui_story_5079_50791200_42_dialog_content = "Dorme, Pact.",
  ui_story_5079_50791200_43_dialog_content = "Mas... Mas eu quero que a mãe me abrace novamente...",
  ui_story_5079_50791200_44_dialog_content = "Chega! Isso não é uma férias; estamos correndo por nossas vidas! Os Eclipsitas lá fora—",
  ui_story_5079_50791200_45_dialog_content = "... Pelo bem da sua mãe, temos que fazer o nosso melhor para sobreviver. Você entende?",
  ui_story_5079_50791200_46_dialog_content = "Eu... Eu não quero entender! Eu só quero minha mãe!",
  ui_story_5079_50791200_47_dialog_content = "...",
  ui_story_5079_50791200_48_dialog_content = "Pai é o pior... Como ele poderia me dizer para esquecer a mãe?",
  ui_story_5079_50791200_49_dialog_content = "Caminhei todo o caminho até aqui, mas ele ainda não veio me procurar...",
  ui_story_5079_50791200_50_dialog_content = "Ele é o pior... Como ele poderia me dizer para esquecer a mãe?",
  ui_story_5079_50791200_51_dialog_content = "Hã? Eu vejo luz lá dentro...",
  ui_story_5079_50791200_52_dialog_content = "<color=#e8d9bb>*passos*</color>",
  ui_story_5079_50791200_53_dialog_content = "Isso é...",
  ui_story_5079_50791200_54_dialog_content = "Um ídolo?",
  ui_story_5079_50791200_55_dialog_content = "Se realmente existe um deus lá fora, então me devolva minha mãe...",
  ui_story_5079_50791200_56_dialog_content = "Não, espera... Minha mãe disse que eu preciso ser respeitoso quando oro aos deuses. Eu tenho que ser mais maduro sobre isso...",
  ui_story_5079_50791200_57_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_5079_50791200_58_dialog_content = "Desejo que toda essa luta acabe. Desejo ter a força para proteger minha família...",
  ui_story_5079_50791200_59_dialog_content = "Por favor, conceda meu desejo, e eu te seguirei e venerarei pelo resto da minha vida...",
  ui_story_5079_50791200_X59_dialog_content = "Eu-Eu até...",
  ui_story_5079_50791200_60_dialog_content = "<color=#e8d9bb>Por um longo tempo, a garotinha ajoelhou-se diante do ídolo em silenciosa oração.</color>",
  ui_story_5079_50791200_61_dialog_content = "<color=#e8d9bb>Na tranquilidade da escuridão, seu coração cansado lentamente adentrou um sono profundo.</color>",
  ui_story_5079_50791200_62_dialog_content = "<color=#e8d9bb>Barulho, barulho—</color>",
  ui_story_5079_50791200_63_dialog_content = "...",
  ui_story_5079_50791200_64_dialog_content = "Como assim?",
  ui_story_5079_50791200_65_dialog_content = "Huh? Qu-Quando eu adormeci...?",
  ui_story_5079_50791200_66_dialog_content = "Pact? Então é aqui que você esteve se escondendo! Você tem alguma ideia de quanto tempo eu estive procurando por você?",
  ui_story_5079_50791200_67_dialog_content = "...",
  ui_story_5079_50791200_68_dialog_content = "!!!",
  ui_story_5079_50791200_69_dialog_content = "P-Por que você está me olhando assim...?",
  ui_story_5079_50791200_70_dialog_content = "Pact, preciso que você caminhe lentamente em minha direção sem olhar para trás. Depressa!",
  ui_story_5079_50791200_71_dialog_content = "Sem olhar para trás? Há algo atrás de mim?",
  ui_story_5079_50791200_72_dialog_content = "...",
  ui_story_5079_50791200_73_dialog_content = "O-O que...?",
  ui_story_5079_50791200_74_dialog_content = "O que... é isso?",
  ui_story_5079_50791200_75_dialog_content = "Pact, preciso que você caminhe lentamente em minha direção. Não tenha medo, e não olhe para trás...",
  ui_story_5079_50791200_76_dialog_content = "T-Tá... Estou indo...",
  ui_story_5079_50791200_77_dialog_content = "Graaah!",
  ui_story_5079_50791200_78_dialog_content = "O quê?! De todas as horas ruins...",
  ui_story_5079_50791200_79_dialog_content = "Encontre um lugar para se esconder, Pact! Eu vou lidar com esses monstros!!!",
  ui_story_5079_50791200_80_dialog_content = "Pai... Não... Você não tem chance contra os Eclipsitas...",
  ui_story_5079_50791200_81_dialog_content = "Graaah!",
  ui_story_5079_50791200_82_dialog_content = "Não... Nãããão!!!",
  ui_story_5079_50791200_83_dialog_content = "!",
  ui_story_5079_50791200_84_dialog_content = "Graaah...",
  ui_story_5079_50791200_85_dialog_content = "Hã? Aquele ataque agora... Fui eu que fiz isso?",
  ui_story_5079_50791200_86_dialog_content = "Essa coisa... Essa roda estranha... É minha arma!",
  ui_story_5079_50791200_87_dialog_content = "Posso usar Luminatics, pai! Eu... Eu posso protegê-lo agora!",
  ui_story_5079_50791200_88_dialog_content = "Não precisamos mais nos esconder! ... Pai? Por que você parece tão chateado?",
  ui_story_5079_50791200_89_dialog_content = "...",
  ui_story_5079_50791200_90_dialog_content = "Entendo...",
  ui_story_5079_50791200_91_dialog_content = "Então você era o Deus da Comida o tempo todo?",
  ui_story_5079_50791200_92_dialog_content = "Por favor, conceda meu desejo, e eu te seguirei e venerarei pelo resto da minha vida...",
  ui_story_5079_50791200_93_dialog_content = "Acho que nunca vou me libertar das suas algemas, huh?",
  ui_story_5079_50791200_94_dialog_content = "...",
  ui_story_5079_50791200_95_dialog_content = "Pedra de Caça?",
  ui_story_5079_50791200_96_dialog_content = "...",
  ui_story_5079_50791200_97_dialog_content = "Ei, o que você está fazendo? Eu não te disse para ir lá...",
  ui_story_5079_50791200_98_dialog_content = "!",
  ui_story_5079_50791200_99_dialog_content = "Eles estão se fundindo?",
  ui_story_5079_50791200_100_dialog_content = "Não... Ele está apenas voltando à sua forma original.",
  ui_story_5079_50791200_101_dialog_content = "Esta é a casa da Pedra de Caça. O lugar a que pertence...",
  ui_story_5079_50791200_102_dialog_content = "Ele não estava me seguindo para começar. Todo esse tempo, eu estava impedindo-o de ir para casa...",
  ui_story_5079_50791200_103_dialog_content = "!",
  ui_story_5079_50791200_104_dialog_content = "Se controle, está bem? Você está apenas em casa, só isso... Não precisa ficar tão animado.",
  ui_story_5079_50791200_105_dialog_content = "Ou talvez seja eu... Talvez eu seja simplesmente incapaz de ter esse sentimento.",
  ui_story_5079_50791200_106_dialog_content = "Afinal, eu não tenho mais uma casa para voltar...",
  ui_story_5079_50791200_107_dialog_content = "Eu nunca quis você por perto mesmo. Assim, todo mundo consegue o que quer.",
  ui_story_5079_50791200_108_dialog_content = "Vou procurar pelo pai do Popo agora, então...",
  ui_story_5079_50791200_109_dialog_content = "!",
  ui_story_5079_50791200_110_dialog_content = "Venha junto se quiser, mas se decidir ficar aqui...",
  ui_story_5079_50791200_111_dialog_content = "Então, é adeus.",
  ui_story_5079_50791200_112_dialog_content = "Será para sempre também... Você me ouve?",
  ui_story_5079_50791200_113_dialog_content = "!",
  ui_story_5079_50791200_114_dialog_content = "Pare de fingir já... Você faz parecer uma decisão tão difícil, mas você não está se mexendo nada, está?",
  ui_story_5079_50791200_115_dialog_content = "Eu realmente vou embora! Viu? Estou indo embora...",
  ui_story_5079_50791200_116_dialog_content = "!",
  ui_story_5079_50791200_117_dialog_content = "Tudo bem. Vejo que você já tomou sua decisão.",
  ui_story_5079_50791200_118_dialog_content = "Adeus, Pedra de Caça.",
  ui_story_5079_50791301_1_dialog_content = "<color=#e8d9bb>*passos*</color>",
  ui_story_5079_50791301_2_dialog_content = "Esse idiota, realmente ficou para trás... Deve ser bom ter um lugar para chamar de lar.",
  ui_story_5079_50791301_3_dialog_content = "Meu desejo poderia ser concedido tão facilmente? Parece bom demais para ser verdade, e isso me incomoda.",
  ui_story_5079_50791301_4_dialog_content = "Afinal, o que exatamente é essa coisa? Eu ainda não tenho ideia...",
  ui_story_5079_50791301_5_dialog_content = "Ah, mas isso não importa agora! O que importa é que eu consegui o que desejava, certo?",
  ui_story_5079_50791301_6_dialog_content = "...",
  ui_story_5079_50791301_7_dialog_content = "Aí está você!",
  ui_story_5079_50791301_8_dialog_content = "Ei! Você está bem?",
  ui_story_5079_50791301_9_dialog_content = "Argh...",
  ui_story_5079_50791301_10_dialog_content = "Bom, suas lesões não parecem muito graves. Vamos, levante-se!",
  ui_story_5079_50791301_11_dialog_content = "Ei, ei! Agora não é hora para uma soneca... Sua filha está te esperando lá fora!",
  ui_story_5079_50791301_12_dialog_content = "M-Minha filha...",
  ui_story_5079_50791301_13_dialog_content = "Isso mesmo! Você veio aqui para encontrar o Popo, não foi?",
  ui_story_5079_50791301_14_dialog_content = "P-Popo?",
  ui_story_5079_50791301_15_dialog_content = "Popo, é realmente você? Ah, graças a Deus... Estou tão feliz que você está seguro!",
  ui_story_5079_50791301_16_dialog_content = "Eu estava errado, Popo... Eu fui duro demais com você antes. Como eu poderia possivelmente não te querer?",
  ui_story_5079_50791301_17_dialog_content = "Muito difícil? Urgh... Minha cabeça...",
  ui_story_5079_50791301_18_dialog_content = "Olha, Popo! Esta é a maior cenoura que já produzi na minha vida! Um dos nossos clientes habituais insistiu para que eu a vendesse para ele, mas eu recusei...",
  ui_story_5079_50791301_19_dialog_content = "*suspiros* Popo ainda se recusa a comer suas cenouras. Que garotinha teimosa.",
  ui_story_5079_50791301_20_dialog_content = "Suponho que terei que comprar alguns doces para ela desta vez... Mas não serei tão generoso na próxima vez que ela recusar sua comida...",
  ui_story_5079_50791301_21_dialog_content = "Popo finalmente aprendeu a usar Luminática, mas... Eu só gostaria que ela pudesse ser um pouco mais bem-educada.",
  ui_story_5079_50791301_22_dialog_content = "Não consigo ensinar nada a ela... Sou um pai tão inútil...",
  ui_story_5079_50791301_23_dialog_content = "Se ao menos houvesse um nobre Auroriano que pudesse ensiná-la, mas eu não conheço ninguém assim...",
  ui_story_5079_50791301_24_dialog_content = "Seu vestido está cheio de buracos de novo! Por que você não se livra dessa coisa feia?",
  ui_story_5079_50791301_25_dialog_content = "Eu... Eu só quero ter uma vida normal com minha filha normal! Isso é pedir demais?",
  ui_story_5079_50791301_26_dialog_content = "Pense! Deve haver alguma maneira de fazer essa coisa desaparecer! Eu... Eu...",
  ui_story_5079_50791301_27_dialog_content = "Esqueça... Eu nunca terei uma loja de alto padrão enquanto eu viver...",
  ui_story_5079_50791301_28_dialog_content = "Mas, no mínimo, temos que viver bem... Eu vou encontrar um arranjo que funcione apenas para você.",
  ui_story_5079_50791301_29_dialog_content = "Como isso soa, Popo?",
  ui_story_5079_50791301_30_dialog_content = "Quer que eu aceite seu arranjo? De jeito nenhum! Especialmente depois que você disse que eu era inútil na sua carta...",
  ui_story_5079_50791301_31_dialog_content = "!",
  ui_story_5079_50791301_32_dialog_content = "Espere... O que eu vi agora? Você é... o pai do Popo...",
  ui_story_5079_50791301_33_dialog_content = "Desculpe, mas eu não sou sua filha. Você terá que guardar essas palavras para ela, não para mim.",
  ui_story_5079_50791301_34_dialog_content = "Eu sou... Eu sou apenas o detetive que está ajudando Popo a te encontrar. Me diga, você tem alguma ideia do que está acontecendo em Folta, ou o que está causando isso?",
  ui_story_5079_50791301_35_dialog_content = "Hã? Algo está acontecendo em Folta?",
  ui_story_5079_50791301_36_dialog_content = "Não tenho ideia do que você está falando. O que está acontecendo na nossa cidade? Espere...",
  ui_story_5079_50791301_37_dialog_content = "Não é você... a mocinha que eu vi no trem esta manhã?",
  ui_story_5079_50791301_38_dialog_content = "Por favor, me perdoe por confundi-la com minha filha! Eu não quis ofender, senhorita!",
  ui_story_5079_50791301_39_dialog_content = "Você disse que tem ajudado ela? Uma nobre senhora refinada como você?",
  ui_story_5079_50791301_40_dialog_content = "Eu sabia pela sua aparência digna que você era uma pessoa nobre e de alta classe!",
  ui_story_5079_50791301_41_dialog_content = "Acho que meu pai estava mentindo quando disse que pessoas bem vestidas se comportam melhor que as outras!",
  ui_story_5079_50791301_42_dialog_content = "Parece que Popo se lembra claramente das palavras de seu pai...",
  ui_story_5079_50791301_43_dialog_content = "Mas eu dificilmente acho que o caráter de alguém tem algo a ver com suas roupas.",
  ui_story_5079_50791301_44_dialog_content = "Há muitas pessoas de aparência digna que fazem coisas vergonhosas nos bastidores, assim como há pessoas que ajudam os menos privilegiados, mesmo vestindo trapos.",
  ui_story_5079_50791301_45_dialog_content = "Sim... Acredito que você esteja certo.",
  ui_story_5079_50791301_46_dialog_content = "E nesse sentido, ser excessivamente bajulador não é ser educado. Se alguma coisa, isso apenas faz as pessoas gostarem menos de você...",
  ui_story_5079_50791301_47_dialog_content = "Eu... Eu sinto muito...",
  ui_story_5079_50791301_48_dialog_content = "Urgh... Esqueça. Eu não deveria estar te ensinando boas maneiras agora...",
  ui_story_5079_50791301_49_dialog_content = "Mesmo que você não saiba o que está acontecendo na cidade, você deve ter alguma ideia do que está por trás do cheiro de cenouras nesta caverna, certo?",
  ui_story_5079_50791301_50_dialog_content = "Se não resolvermos isso, sua loja de cenouras será fechada para sempre.",
  ui_story_5079_50791301_51_dialog_content = "O cheiro de cenouras... Ah! Será que tem algo a ver com a coisa que me atacou?",
  ui_story_5079_50791301_52_dialog_content = "Que \"coisa\"?",
  ui_story_5079_50791301_53_dialog_content = "Você pode não acreditar em mim... mas acho que fui nocauteado por um monstro gigante de cenoura.",
  ui_story_5079_50791301_54_dialog_content = "Um monstro de cenoura? Poderia ser algum tipo de Eclipsite não descoberto?",
  ui_story_5079_50791301_55_dialog_content = "E-Eu não tenho certeza, mas... isso tudo pode ser culpa minha...",
  ui_story_5079_50791301_56_dialog_content = "Afinal, minha filha Popo fugiu de casa por minha causa, e eu não consegui encontrá-la em lugar nenhum...",
  ui_story_5079_50791301_57_dialog_content = "Então comecei a procurar respostas nas superstições populares, e gastei uma enorme soma de dinheiro em um chamado \"tributo supremo\".",
  ui_story_5079_50791301_58_dialog_content = "Eu queria oferecer isso ao Deus da Comida e implorar à divindade para encontrar minha filha.",
  ui_story_5079_50791301_59_dialog_content = "\"Uma grande soma de dinheiro\"? Eu não fazia ideia de que você se importava tanto com o Popo...",
  ui_story_5079_50791301_60_dialog_content = "Claro que sim! Ela é minha filha, além de ser a única família que me resta neste mundo!",
  ui_story_5079_50791301_61_dialog_content = "A única família que lhe resta... Parece que você realmente acredita nisso, então como as coisas acabaram assim?",
  ui_story_5079_50791301_62_dialog_content = "Eu... Eu não fazia ideia de que a suprema homenagem seria absorvida por uma cenoura disfarçada de ídolo!",
  ui_story_5079_50791301_63_dialog_content = "Naquele momento, transformou-se em um monstro enorme e jurou destruir todos que odeiam cenouras.",
  ui_story_5079_50791301_64_dialog_content = "Não consigo me lembrar do que aconteceu depois disso...",
  ui_story_5079_50791301_65_dialog_content = "Você pode descrever para mim esse \"tributo supremo\"?",
  ui_story_5079_50791301_66_dialog_content = "Era... um objeto brilhante, em forma de diamante...",
  ui_story_5079_50791301_67_dialog_content = "Espere um segundo... Isso soa exatamente como uma Semente! A coisa que pode transformar Aurorians em Eclipsitas!",
  ui_story_5079_50791301_68_dialog_content = "Isso explicaria por que esse cheiro de cenoura atraiu todos aqueles Eclipsites lá fora!",
  ui_story_5079_50791301_69_dialog_content = "Se você realmente ama sua filha, deveria se esforçar mais para se dar bem com ela, e não recorrer a esses métodos loucos quando as coisas dão errado!",
  ui_story_5079_50791301_70_dialog_content = "O que você fará se as consequências forem irreversíveis? Porque essa pode ser uma possibilidade agora!",
  ui_story_5079_50791301_71_dialog_content = "Popo é uma boa menina... Mesmo que vocês briguem o tempo todo, ela está sempre pensando em você...",
  ui_story_5079_50791301_72_dialog_content = "Eu... Eu sei que ela é uma boa criança. Eu sei disso melhor do que ninguém.",
  ui_story_5079_50791301_73_dialog_content = "Mas as atitudes de uma criança precisam ser moldadas cedo, e você não pode elogiá-las por tudo que fazem. Eu apenas—",
  ui_story_5079_50791301_74_dialog_content = "Você apenas o quê? Isso não passa de um pensamento unilateral e ilusório!",
  ui_story_5079_50791301_75_dialog_content = "Você já realmente ouviu os sentimentos dela sobre isso?",
  ui_story_5079_50791301_76_dialog_content = "Você gosta de cenouras, então acha que sua criança também tem que gostar delas.",
  ui_story_5079_50791301_77_dialog_content = "Você quer que ela aprenda Luminatics, então ela não tem escolha a não ser aprender.",
  ui_story_5079_50791301_78_dialog_content = "E agora que ela pode usar Luminática, aposto que você gostaria que a Luminática dela fosse tão poderosa e graciosa quanto a de um nobre de Lumópolis! Esse \"amor\" seu—",
  ui_story_5079_50791301_79_dialog_content = "Você não acha que é demais para ela suportar?",
  ui_story_5079_50791301_80_dialog_content = "Eu... Espere, Popo pode usar Luminatics agora?",
  ui_story_5079_50791301_81_dialog_content = "...",
  ui_story_5079_50791301_82_dialog_content = "... Esqueça o que eu disse. Não estou tentando mudar nada aqui, mas só espero que você tente ser mais digno do amor de Popo.",
  ui_story_5079_50791301_83_dialog_content = "Sim, ela aprendeu a usar Luminatics... e tudo por causa dos Eclipsitas que você trouxe para cá.",
  ui_story_5079_50791301_84_dialog_content = "Ainda assim... Sementes são geralmente apenas absorvidas por Aurorianos. Como uma cenoura conseguiu usá-la para se tornar um Eclipsita?",
  ui_story_5079_50791301_85_dialog_content = "Além disso, não me lembro de ver nenhum monstro de cenoura no caminho até aqui... Espere um minuto...",
  ui_story_5079_50791301_86_dialog_content = "...",
  ui_story_5079_50791301_87_dialog_content = "Não são esses os fragmentos daquele ídolo que vi mais cedo? Por que aqui?",
  ui_story_5079_50791301_88_dialog_content = "Ah não! Não me diga que esse ídolo é...",
  ui_story_5079_50791301_89_dialog_content = "Eu... Eu acho que consigo sentir o cheiro da fonte do sabor de cenoura! Como se estivesse de alguma forma conectado a mim!",
  ui_story_5079_50791301_90_dialog_content = "O cheiro de cenouras vem da caverna do Deus da Comida! Tenho certeza disso agora!",
  ui_story_5079_50791301_91_dialog_content = "Eu também ouço uma voz... Está me dizendo para me aproximar!",
  ui_story_5079_50791301_92_dialog_content = "Popo está em apuros!",
  ui_story_5079_50791301_93_dialog_content = "O que seria?",
  ui_story_5079_50791301_94_dialog_content = "Ela está esperando bem na entrada da caverna! Temos que voltar para ela!",
  ui_story_5079_50791301_95_dialog_content = "Graaah!",
  ui_story_5079_50791301_96_dialog_content = "Eu não tenho tempo para desperdiçar com você, agora saia do meu caminho!",
  ui_story_5079_50791401_1_dialog_content = "<color=#828282>Vuuush!</color>",
  ui_story_5079_50791401_2_dialog_content = "Graah...",
  ui_story_5079_50791401_3_dialog_content = "Essa foi a última. Nós deveríamos—",
  ui_story_5079_50791401_4_dialog_content = "...",
  ui_story_5079_50791401_5_dialog_content = "Ei! Não sabemos o que nos espera lá fora! Você não pode usar Luminática, então fique atrás de mim!",
  ui_story_5079_50791401_6_dialog_content = "Popo! Popo, onde você está?",
  ui_story_5079_50791401_7_dialog_content = "Tsk, ele é tão ruim em ouvir quanto o Popo. Acho que eles realmente são parecidos...",
  ui_story_5079_50791401_8_dialog_content = "<size=45>Popo—</size>",
  ui_story_5079_50791401_9_dialog_content = "Huh? Acabei de ouvir a voz do pai?",
  ui_story_5079_50791401_10_dialog_content = "<size=45>Pai! Estou aqui!</size>",
  ui_story_5079_50791401_11_dialog_content = "Fique exatamente aí, Popo! Estou indo te buscar!",
  ui_story_5079_50791401_12_dialog_content = "Pare! Eu ouço algo se movendo...",
  ui_story_5079_50791401_13_dialog_content = "Clac... Clac, clac, clac—",
  ui_story_5079_50791401_14_dialog_content = "Bum!",
  ui_story_5079_50791401_15_dialog_content = "Po...",
  ui_story_5079_50791401_16_dialog_content = "Popopo!",
  ui_story_5079_50791401_17_dialog_content = "Eu sabia! O monstro da cenoura se disfarçou de ídolo lá fora!",
  ui_story_5079_50791401_18_dialog_content = "Escória sem vergonha... Tem se disfarçado como o Deus da Comida e pegando as oferendas das pessoas para si mesmo!",
  ui_story_5079_50791401_19_dialog_content = "Po... Popo!",
  ui_story_5079_50791401_20_dialog_content = "Espere, para onde está indo? Ei! Seu oponente está aqui!",
  ui_story_5079_50791401_21_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5079_50791401_22_dialog_content = "Ele ignora totalmente meus ataques! Ei! Pare aí mesmo!",
  ui_story_5079_50791401_23_dialog_content = "Popopo!",
  ui_story_5079_50791401_24_dialog_content = "S-Fique para trás... Não chegue mais perto!",
  ui_story_5079_50791401_25_dialog_content = "T-Tome isso!",
  ui_story_5079_50791401_26_dialog_content = "<color=#e8d9bb>Plaft—</color>",
  ui_story_5079_50791401_27_dialog_content = "Po? Popopo...",
  ui_story_5079_50791401_28_dialog_content = "Os Luminatics de Popo... Não acredito que finalmente estou vendo os poderes da minha filha com meus próprios olhos...",
  ui_story_5079_50791401_29_dialog_content = "É realmente a hora de ficar olhando com espanto? Vá encontrar um lugar seguro para se esconder!",
  ui_story_5079_50791401_30_dialog_content = "Mas minha filha...",
  ui_story_5079_50791401_31_dialog_content = "Deixe-a comigo!",
  ui_story_5079_50791401_32_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5079_50791401_33_dialog_content = "Popopo... Seus ataques são inúteis contra mim! Não tenho interesse em você...",
  ui_story_5079_50791401_34_dialog_content = "...",
  ui_story_5079_50791401_35_dialog_content = "Mas você, Popo... Mesmo com um nome tão maravilhoso, ainda despreza as cenouras!",
  ui_story_5079_50791401_36_dialog_content = "O seu ódio por eles alimenta a minha força!",
  ui_story_5079_50791401_37_dialog_content = "Eu estava certo. Essa coisa está realmente atrás do Popo!",
  ui_story_5079_50791401_38_dialog_content = "Pedra de Caça! Não, espera, não é—",
  ui_story_5079_50791401_39_dialog_content = "Popopo! Você está se referindo a isso, por acaso?",
  ui_story_5079_50791401_40_dialog_content = "!",
  ui_story_5079_50791401_41_dialog_content = "Pedra de Caça... Devolva isso para mim!",
  ui_story_5079_50791401_42_dialog_content = "Você roda inútil! Você realmente vai deixar esse monstro usar você assim? Venha aqui agora mesmo...",
  ui_story_5079_50791401_43_dialog_content = "Argh...",
  ui_story_5079_50791401_44_dialog_content = "Popopo!",
  ui_story_5079_50791401_45_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5079_50791401_46_dialog_content = "A Pedra de Caça... Ela não está mais me ouvindo?",
  ui_story_5079_50791401_47_dialog_content = "Estou muito grato pela arma que você me deu.",
  ui_story_5079_50791401_48_dialog_content = "Mas acima de tudo, sou grato a você, Popo...",
  ui_story_5079_50791401_49_dialog_content = "Tudo que eu preciso é de mais uma mordida, um último pedaço delicioso de ódio, e eu posso governar cada pedaço de comida neste mundo!",
  ui_story_5079_50791401_50_dialog_content = "Em breve, eu não apenas abençoarei Folta, mas todo Astra com o sabor crocante e irresistível das cenouras!",
  ui_story_5079_50791401_51_dialog_content = "Popopo!",
  ui_story_5079_50791401_52_dialog_content = "Não... Você não pode! O mundo não pode acabar assim...",
  ui_story_5079_50791401_53_dialog_content = "\"Não posso\", você diz? Popopo... Eu discordo! Afinal, eu nunca teria me tornado tão poderoso se você não tivesse me abandonado aqui!",
  ui_story_5079_50791401_54_dialog_content = "Po... Po...",
  ui_story_5079_50791401_55_dialog_content = "Como... Como você poderia deixar uma cenourinha tão fofa sozinha aqui?",
  ui_story_5079_50791401_56_dialog_content = "Está escuro... Tão escuro... Sem nutrientes... Sem forças...",
  ui_story_5079_50791401_57_dialog_content = "Todo-Poderoso Deus da Comida, eu desejo viver em um mundo sem cenouras!",
  ui_story_5079_50791401_58_dialog_content = "Por que qualquer um de nós tem que comer algo tão nojento que nem deveria existir?",
  ui_story_5079_50791401_59_dialog_content = "Eu imploro a você! Por favor, exclua as cenouras de todas as receitas conhecidas no mundo!",
  ui_story_5079_50791401_60_dialog_content = "Eu... nunca deveria ter... aparecido neste mundo...",
  ui_story_5079_50791401_61_dialog_content = "Odiado, abandonado, desnecessário...",
  ui_story_5079_50791401_62_dialog_content = "Ó poderoso Deus da Comida, por favor, abençoe nossa família com paz e segurança...",
  ui_story_5079_50791401_63_dialog_content = "Ouça meu apelo, bondoso Deus da Comida! Por favor, faça aquela garota se apaixonar por mim!",
  ui_story_5079_50791401_64_dialog_content = "Por favor, aceite minhas oferendas, Deus da Comida...",
  ui_story_5079_50791401_65_dialog_content = "Deus da Comida, Deus da Comida... É apenas uma estátua, não é? Por que todos continuam pedindo para que ela conceda seus desejos?",
  ui_story_5079_50791401_66_dialog_content = "Eles rezam e imploram, mas nada acontece... Não merece a adoração deles...",
  ui_story_5079_50791401_67_dialog_content = "Mas eu sim... Porque sou real! Eu estou vivo!",
  ui_story_5079_50791401_68_dialog_content = "Note-me! Olhe para mim! Adore-me! Eu sou melhor do que aquela estátua... porque eu posso fazer seus sonhos se tornarem realidade!",
  ui_story_5079_50791401_69_dialog_content = "...",
  ui_story_5079_50791401_70_dialog_content = "Popopo!",
  ui_story_5079_50791401_71_dialog_content = "Além disso, o Deus da Comida nunca responderá às suas orações. Em seu lugar—",
  ui_story_5079_50791401_72_dialog_content = "Vou apreciar suas generosas ofertas!",
  ui_story_5079_50791401_73_dialog_content = "Ó Deus da Comida, por favor aceite esta cenoura como minha oferta. Um gosto e você saberá exatamente por que eu as odeio tanto.",
  ui_story_5079_50791401_74_dialog_content = "Sim, Popo... Continue odiando eles! Continue me odiando! Isso só me torna mais forte!",
  ui_story_5079_50791401_75_dialog_content = "Ó Deus da Comida, você pode fazer meu irritante marido desaparecer?",
  ui_story_5079_50791401_76_dialog_content = "Sim, sim! Eu concederei com prazer um desejo tão deliciosamente odioso!",
  ui_story_5079_50791401_77_dialog_content = "... Por favor, aceite esta suprema homenagem em troca de encontrar minha filha...",
  ui_story_5079_50791401_78_dialog_content = "Sim... Sim! Você faz ideia de quanto tempo eu esperei por esse momento?",
  ui_story_5079_50791401_79_dialog_content = "... Hum?",
  ui_story_5079_50791401_80_dialog_content = "Po... Popopo!",
  ui_story_5079_50791401_81_dialog_content = "...",
  ui_story_5079_50791401_82_dialog_content = "Então tudo isso aconteceu por minha causa?",
  ui_story_5079_50791401_83_dialog_content = "Esse monstro de cenoura... era a cenoura que deixei aqui há muito tempo.",
  ui_story_5079_50791401_84_dialog_content = "De fato, e agora chegou a hora de te pagar na íntegra!",
  ui_story_5079_50791401_85_dialog_content = "Ahhh—",
  ui_story_5079_50791401_86_dialog_content = "Popo!",
  ui_story_5079_50791401_87_dialog_content = "O monstro de cenoura está usando o poder da Pedra de Caça para fazer espinhos crescerem em seus tentáculos!",
  ui_story_5079_50791401_88_dialog_content = "Tsk... Se a Pedra de Caça não tivesse se tornado sua arma, essa cenoura estúpida não teria sido tão poderosa!",
  ui_story_5079_50791401_89_dialog_content = "Agora não é a hora para você tornar as coisas ainda mais difíceis para mim, seu idiota!",
  ui_story_5079_50791401_90_dialog_content = "Solte... Solte a minha filha!",
  ui_story_5079_50791401_91_dialog_content = "Uhh?",
  ui_story_5079_50791401_92_dialog_content = "Espere, o que você acha que está fazendo? Você nem mesmo sabe usar Luminatics...",
  ui_story_5079_50791401_93_dialog_content = "Se eu não posso usar Luminatics, usarei paus e pedras para lutar.",
  ui_story_5079_50791401_94_dialog_content = "Mesmo sem esses, eu ainda tenho meus punhos!",
  ui_story_5079_50791401_95_dialog_content = "Você está simplesmente pedindo para ser morto!",
  ui_story_5079_50791401_96_dialog_content = "*tosse* Aquele monstro tem minha garotinha. Mesmo que me custe a vida, eu tenho que salvá-la!",
  ui_story_5079_50791401_97_dialog_content = "Solte-a!",
  ui_story_5079_50791401_98_dialog_content = "Eu te disse para deixá-la comigo... Urgh...",
  ui_story_5079_50791401_99_dialog_content = "Minha cabeça... Por que isso tinha que acontecer agora...",
  ui_story_5079_50791401_100_dialog_content = "Quem é você? Afaste-se da minha filha!",
  ui_story_5079_50791401_101_dialog_content = "Solte-a agora mesmo, ou você vai se arrepender!",
  ui_story_5079_50791401_102_dialog_content = "Afaste-se dela agora mesmo, ou vai se arrepender!",
  ui_story_5079_50791401_103_dialog_content = "Pare, deixe-me...",
  ui_story_5079_50791401_104_dialog_content = "Popopo!",
  ui_story_5079_50791401_105_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5079_50791401_106_dialog_content = "Urgh... É tudo o que você tem? Venha até mim, monstro!",
  ui_story_5079_50791401_107_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5079_50791401_108_dialog_content = "Ainda não acabei... Solte-a!",
  ui_story_5079_50791401_109_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5079_50791401_110_dialog_content = "Isso... Isso ainda não acabou...",
  ui_story_5079_50791401_111_dialog_content = "Rápido, Popo... Eu vou tirar os espinhos para você...",
  ui_story_5079_50791401_112_dialog_content = "<color=#e8d9bb>Esfaquear—</color>",
  ui_story_5079_50791401_113_dialog_content = "Pai... Suas mãos estão sangrando demais! Nesse ritmo, você vai—",
  ui_story_5079_50791401_114_dialog_content = "Não se preocupe comigo! Apenas vá, pai! Isso é... tudo culpa minha de qualquer maneira...",
  ui_story_5079_50791401_115_dialog_content = "É por isso que eu deveria—",
  ui_story_5079_50791401_116_dialog_content = "Chega! Fui eu quem comprou aquele maldito tributo... Se ao menos eu fosse mais compreensivo...",
  ui_story_5079_50791401_117_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5079_50791401_118_dialog_content = "Urgh... Finalmente está soltando? A-Apressa-te, Popo...",
  ui_story_5079_50791401_119_dialog_content = "Pai…",
  ui_story_5079_50791401_120_dialog_content = "Eu preciso que você vire e caminhe em direção à entrada da caverna... Não tenha medo, e não olhe para trás...",
  ui_story_5079_50791401_121_dialog_content = "Pact, preciso que você caminhe lentamente em minha direção. Não tenha medo, e não olhe para trás...",
  ui_story_5079_50791401_122_dialog_content = "D-Depressa...",
  ui_story_5079_50791401_123_dialog_content = "F-Pai?",
  ui_story_5079_50791401_124_dialog_content = "Desta vez, não estou orando para ninguém ou qualquer outra coisa...",
  ui_story_5079_50791401_125_dialog_content = "Vou salvar minha família com minhas próprias mãos!",
  ui_story_5079_50791501_1_dialog_content = "<color=#828282>Vuuush!</color>",
  ui_story_5079_50791501_2_dialog_content = "Po...",
  ui_story_5079_50791501_3_dialog_content = "*suspirando* Finalmente...",
  ui_story_5079_50791501_4_dialog_content = "Você ainda consegue se mover, Popo? Você precisa... se apressar...",
  ui_story_5079_50791501_5_dialog_content = "O monstro da cenoura está atrás de você. Se ele conseguir absorver seu ódio, não teremos chance contra ele...",
  ui_story_5079_50791501_6_dialog_content = "Mas... Mas meu pai, ele...",
  ui_story_5079_50791501_7_dialog_content = "Eu trarei seu pai para você depois que eu derrotar aquilo.",
  ui_story_5079_50791501_8_dialog_content = "Mas agora você precisa sair daqui, entendeu? Este será o seu maior desafio até agora!",
  ui_story_5079_50791501_9_dialog_content = "Eu... Eu consigo!",
  ui_story_5079_50791501_10_dialog_content = "Não! Não há como escapar de mim!",
  ui_story_5079_50791501_11_dialog_content = "Seu oponente está aqui!",
  ui_story_5079_50791501_12_dialog_content = "<color=#828282>Vuuush!</color>",
  ui_story_5079_50791501_13_dialog_content = "Po...",
  ui_story_5079_50791501_14_dialog_content = "Tsc, ainda sem danos, hein? Parece que...",
  ui_story_5079_50791501_15_dialog_content = "Popopo... Como se estivesse faltando algo, sim?",
  ui_story_5079_50791501_16_dialog_content = "Se eu não estou enganado, você usou quase toda a sua energia, não usou?",
  ui_story_5079_50791501_17_dialog_content = "O que você poderia fazer sem essa arma?",
  ui_story_5079_50791501_18_dialog_content = "Tsk... Não me subestime, monstro!",
  ui_story_5079_50791501_19_dialog_content = "<color=#e8d9bb>Vuuush! Smack—</color>",
  ui_story_5079_50791501_20_dialog_content = "...",
  ui_story_5079_50791501_21_dialog_content = "Já no seu limite? Que decepcionante!",
  ui_story_5079_50791501_22_dialog_content = "Com esta arma que você me deu... Eu estou apenas começando!",
  ui_story_5079_50791501_23_dialog_content = "Ugh!",
  ui_story_5079_50791501_24_dialog_content = "Então este é o poder da Pedra de Caça... Heh, esta é a minha primeira vez... experimentando-o por mim mesmo...",
  ui_story_5079_50791501_25_dialog_content = "Acho que também deveria provar meu poder para você...",
  ui_story_5079_50791501_26_dialog_content = "<color=#e8d9bb>Vuuush! Smack—</color>",
  ui_story_5079_50791501_27_dialog_content = "*tosse* Você não está me dando nenhuma folga hoje, está?",
  ui_story_5079_50791501_28_dialog_content = "É este o ressentimento que você sente por mim, Hunting Stone? Heheh...",
  ui_story_5079_50791501_29_dialog_content = "Eu mereço isso, eu suponho.",
  ui_story_5079_50791501_30_dialog_content = "Eu pensei que você se recusou a vir comigo, mas você estava sob o controle deste monstro de cenoura o tempo todo...",
  ui_story_5079_50791501_31_dialog_content = "Você tem me ajudado todo esse tempo, mas eu dei sua bondade como garantida e constantemente reclamei sobre me livrar de você...",
  ui_story_5079_50791501_32_dialog_content = "Eu continuava dizendo a mim mesmo que era isso que eu queria... Eu me prendi em uma mentira teimosa.",
  ui_story_5079_50791501_33_dialog_content = "E por causa disso... Eu te entreguei ao inimigo.",
  ui_story_5079_50791501_34_dialog_content = "<color=#e8d9bb>Vuuush! Smack—</color>",
  ui_story_5079_50791501_35_dialog_content = "Tsk, eu não sei mais o que fazer...",
  ui_story_5079_50791501_36_dialog_content = "Popopo! Sinta a picada esmagadora dos meus tentáculos fortalecidos!",
  ui_story_5079_50791501_37_dialog_content = "Aaahhhh!",
  ui_story_5079_50791501_38_dialog_content = "...",
  ui_story_5079_50791501_39_dialog_content = "Urgh... Eu estou bem. Afinal, essa não é a primeira vez... que fui amarrado por Hunting Stone.",
  ui_story_5079_50791501_40_dialog_content = "Ainda bem que a Popo não está aqui para ver isso, senão ela jogaria ainda mais insultos em mim...",
  ui_story_5079_50791501_41_dialog_content = "Ele também não está aqui para me salvar desta vez...",
  ui_story_5079_50791501_42_dialog_content = "O único que pode me ajudar agora...",
  ui_story_5079_50791501_43_dialog_content = "...",
  ui_story_5079_50791501_44_dialog_content = "Isso tudo parece tão familiar...",
  ui_story_5079_50791501_45_dialog_content = "... Ai.",
  ui_story_5079_50791501_46_dialog_content = "Sim, lute e sofra... Isso só fará suas amarras ficarem ainda mais apertadas!",
  ui_story_5079_50791501_47_dialog_content = "Eu... Eu não preciso que você me diga isso... Mas...",
  ui_story_5079_50791501_48_dialog_content = "E-Eu não quero perder... Pedra de Caça.",
  ui_story_5079_50791501_49_dialog_content = "Eu não quero perder... o direito de ter você ao meu lado...",
  ui_story_5079_50791501_50_dialog_content = "...",
  ui_story_5079_50791501_51_dialog_content = "Você não sente falta de rolar sobre o meu rosto quando estou dormindo?",
  ui_story_5079_50791501_52_dialog_content = "Ou assustando as pessoas no pior momento possível?",
  ui_story_5079_50791501_53_dialog_content = "Não sente falta de furar meu vestido acidentalmente, ou até mesmo de propósito?",
  ui_story_5079_50791501_55_dialog_content = "...",
  ui_story_5079_50791501_56_dialog_content = "Eu... pertenço... a Pact...",
  ui_story_5079_50791501_57_dialog_content = "Mas... por favor... lembre-se...",
  ui_story_5079_50791501_58_dialog_content = "Minha força... tudo vem...",
  ui_story_5079_50791501_59_dialog_content = "De... você!",
  ui_story_5079_50791501_60_dialog_content = "Pedra de Caça... Você consegue realmente falar?",
  ui_story_5079_50791501_61_dialog_content = "O que são essas imagens que estou vendo?",
  ui_story_5079_50791501_62_dialog_content = "São essas... minhas primeiras memórias com a Pedra de Caça?",
  ui_story_5079_50791501_63_dialog_content = "Ai... Esse poder... Dói mesmo.",
  ui_story_5079_50791501_64_dialog_content = "Não... Não assim! Eu quero usar meu poder para combater os Eclipsitas...",
  ui_story_5079_50791501_65_dialog_content = "Para não perder o controle neste lugar...",
  ui_story_5079_50791501_66_dialog_content = "Barulho, barulho...",
  ui_story_5079_50791501_67_dialog_content = "Hã? Meu poder... quebrou aquele ídolo?",
  ui_story_5079_50791501_68_dialog_content = "Não... Ainda está lá. Você, por outro lado... Foi abandonado?",
  ui_story_5079_50791501_69_dialog_content = "Assim como a divindade nos abandonou na Cidade Velha e nos deixou para morrer nas mãos dos Eclipsitas...",
  ui_story_5079_50791501_70_dialog_content = "Perdi minha mãe e minha casa... Pelo que sabemos, meu pai e eu podemos ser separados pelos Eclipsitas amanhã.",
  ui_story_5079_50791501_71_dialog_content = "E você... Você terá que passar o resto de seus dias no chão frio, olhando para a estátua que já foi sua...",
  ui_story_5079_50791501_72_dialog_content = "Dói? Você pode me dizer... por que temos que viver com esse tipo de dor?",
  ui_story_5079_50791501_73_dialog_content = "Não... Não é isso...",
  ui_story_5079_50791501_74_dialog_content = "Você e eu... Não somos iguais... então pare de fingir ser tão miserável.",
  ui_story_5079_50791501_75_dialog_content = "Sua estátua está bem ali, então você ainda tem um lugar para chamar de casa... Está tudo bem, apenas use meu poder para retornar ao seu lugar de direito...",
  ui_story_5079_50791501_76_dialog_content = "<color=#e8d9bb>A garota pegou o pedaço quebrado da estátua como se fosse a última brasa em um mundo de noite eterna.</color>",
  ui_story_5079_50791501_77_dialog_content = "<color=#e8d9bb>Com um pequeno, mas autojustificado desejo, ela colocou toda sua força nele...</color>",
  ui_story_5079_50791501_78_dialog_content = "...",
  ui_story_5079_50791501_79_dialog_content = "Agora vá. Volte para casa...",
  ui_story_5079_50791501_80_dialog_content = "...",
  ui_story_5079_50791501_81_dialog_content = "Você está dizendo... que quer ficar comigo? Você... realmente faria isso?",
  ui_story_5079_50791501_82_dialog_content = "Meu poder... Parece muito mais calmo agora. Você está me ajudando a carregar a maior parte do fardo?",
  ui_story_5079_50791501_83_dialog_content = "Sinto-me tão quente e confortável agora... Obrigado... Muito obrigado...",
  ui_story_5079_50791501_84_dialog_content = "Eu... fui eu quem pediu para Hunting Stone ficar comigo?",
  ui_story_5079_50791501_85_dialog_content = "Fui eu quem deu a ele o meu poder...",
  ui_story_5079_50791501_86_dialog_content = "Sim... Esse poder... Tudo pertence a você.",
  ui_story_5079_50791501_87_dialog_content = "Você estava tão com medo de decepcionar seu pai... então você se recusou a confiar em sua própria força.",
  ui_story_5079_50791501_88_dialog_content = "Por essa razão, você fez acreditar que esse poder veio de mim...",
  ui_story_5079_50791501_89_dialog_content = "Não sou tão fraco quanto você me faz parecer... Eu apenas esqueci, só isso.",
  ui_story_5079_50791501_90_dialog_content = "Talvez, mas em algum lugar profundo do seu coração, você sempre se lembra.",
  ui_story_5079_50791501_91_dialog_content = "Não era como se você não tivesse confiança em suas habilidades, na verdade, você apenas queria que alguém ficasse ao seu lado, não importa o que acontecesse...",
  ui_story_5079_50791501_92_dialog_content = "Então foi exatamente isso que fiz. Eu fui seu companheiro silencioso - ou pelo menos eu queria que você se sentisse assim sobre mim.",
  ui_story_5079_50791501_93_dialog_content = "Um companheiro silencioso ainda deve se manifestar quando a situação exigir.",
  ui_story_5079_50791501_94_dialog_content = "Eu gostaria que você tivesse me dito antes que poderia falar. Eu...",
  ui_story_5079_50791501_95_dialog_content = "Eu posso não ser a pessoa mais direta quando se trata dessas coisas... mas ainda assim, às vezes eu quero saber como você se sente!",
  ui_story_5079_50791501_96_dialog_content = "É porque você foi tão honesto agora que finalmente escolhi falar...",
  ui_story_5079_50791501_97_dialog_content = "Ainda me lembro de como você foi gentil comigo naquela noite... Eu estive esperando pelo momento em que você finalmente poderia me aceitar.",
  ui_story_5079_50791501_98_dialog_content = "É por isso que eu posso ficar ao seu lado e te ajudar novamente!",
  ui_story_5079_50791501_99_dialog_content = "Quanto ao seu poder, devolverei tudo a você!",
  ui_story_5079_50791501_100_dialog_content = "Eu conheço sua força e bondade melhor do que qualquer outra pessoa, Pact.",
  ui_story_5079_50791501_101_dialog_content = "Agora supere a dor do seu passado e derrote aquele monstro de cenoura!",
  ui_story_5079_50791501_102_dialog_content = "Humph, você não precisa devolver para mim...",
  ui_story_5079_50791501_103_dialog_content = "Afinal, tem sido <color=#FFB400>nós</color> todo esse tempo, não é?",
  ui_story_5079_50791501_104_dialog_content = "<color=#e8d9bb>Vuuush! Crack!</color>",
  ui_story_5079_50791501_105_dialog_content = "Humph, essas amarras são brincadeira de criança comparadas ao que realmente podemos fazer!",
  ui_story_5079_50791501_106_dialog_content = "Por que essa arma não me obedece?",
  ui_story_5079_50791501_107_dialog_content = "Eu ainda quero saborear um pouco mais do seu sofrimento...",
  ui_story_5079_50791501_108_dialog_content = "Mas parece... que nosso tempo acabou. Espalhe-se, meu delicioso aroma de cenoura!",
  ui_story_5079_50791501_109_dialog_content = "Graaaaaah—",
  ui_story_5079_50791501_110_dialog_content = "Que piada. Você acha que esses peixinhos são suficientes para me parar? Heh... Acho que isso significa que você não é muito mais forte do que eles, hein?",
  ui_story_5079_50791501_111_dialog_content = "Pequeno peixe, pequeno peixe!",
  ui_story_5079_50791501_112_dialog_content = "S-Silêncio!",
  ui_story_5079_50791501_113_dialog_content = "Enquanto essa coisa estiver sob meu controle, você não tem poder aqui!",
  ui_story_5079_50791501_114_dialog_content = "Eu, por outro lado, só preciso consumir o ódio de Popo... Lacaios! Comprem mais tempo para o seu mestre!",
  ui_story_5079_50791501_115_dialog_content = "Graaaaaah—",
  ui_story_5079_50791501_116_dialog_content = "Fugindo com a Pedra de Caça, hein? Grande erro...",
  ui_story_5079_50791501_117_dialog_content = "Enquanto nossos corações forem um, qualquer distância entre nós apenas tornará nosso vínculo mais forte.",
  ui_story_5079_50791501_118_dialog_content = "Não vou deixar você machucar o Popo...",
  ui_story_5079_50791501_119_dialog_content = "E eu não vou deixar mais ninguém fugir com a minha Pedra de Caça!",
  ui_story_5079_50791601_1_dialog_content = "<color=#e8d9bb>Vamo, vamo, vamo!</color>",
  ui_story_5079_50791601_2_dialog_content = "Graaah...",
  ui_story_5079_50791601_3_dialog_content = "Sai da frente, seus fracos!",
  ui_story_5079_50791601_4_dialog_content = "Isso não pode ser! Como você me alcançou tão rápido?",
  ui_story_5079_50791601_5_dialog_content = "<color=#e8d9bb>Vuuush—</color>",
  ui_story_5079_50791601_6_dialog_content = "Mantenha seus tentáculos imundos longe do Popo, seu monstro!",
  ui_story_5079_50791601_7_dialog_content = "É... É você...",
  ui_story_5079_50791601_8_dialog_content = "Desculpe, estou atrasado. Não se preocupe, você está seguro agora...",
  ui_story_5079_50791601_9_dialog_content = "Eu... Eu sabia que você viria me salvar. Eu nunca duvidei disso... nem por um segundo...",
  ui_story_5079_50791601_10_dialog_content = "Desculpe, minha inutilidade me fez ser capturado novamente. Meu pai está—",
  ui_story_5079_50791601_11_dialog_content = "Como eu disse, você não precisa mais se preocupar... Deixe tudo comigo.",
  ui_story_5079_50791601_12_dialog_content = "Não... Não se atreva a me olhar como se eu fosse apenas lixo!",
  ui_story_5079_50791601_13_dialog_content = "Ainda não te mostrei todo o meu poder!",
  ui_story_5079_50791601_14_dialog_content = "Sério? Bom. Eu também não me importaria de ver por mim mesmo.",
  ui_story_5079_50791601_15_dialog_content = "Eu estava pronto para poupar sua vida se você apenas me devolvesse minha Pedra de Caça... mas agora não mais.",
  ui_story_5079_50791601_16_dialog_content = "Já que você insiste em ser assim, permita-me mostrar também todo o meu poder!",
  ui_story_5079_50791602_1_dialog_content = "<color=#828282>Vuuush!</color>",
  ui_story_5079_50791602_2_dialog_content = "Impossível! Meus tentáculos... Ai... Como você pôde...",
  ui_story_5079_50791602_3_dialog_content = "!",
  ui_story_5079_50791602_4_dialog_content = "Não... Não vá!",
  ui_story_5079_50791602_5_dialog_content = "Acabou para você!",
  ui_story_5079_50791602_6_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5079_50791602_7_dialog_content = "Nãooo!",
  ui_story_5079_50791602_8_dialog_content = "!",
  ui_story_5079_50791602_9_dialog_content = "Huh? Por que você está tão feliz? Pare com isso já.",
  ui_story_5079_50791602_10_dialog_content = "Você também não deveria estar feliz, Pact?",
  ui_story_5079_50791602_11_dialog_content = "\"Não vou deixar mais ninguém fugir com a MINHA Pedra de Caça!\" Foi isso que você disse, certo?",
  ui_story_5079_50791602_12_dialog_content = "?",
  ui_story_5079_50791602_13_dialog_content = "Você... Você deve ter me entendido mal! Eu não disse nada disso!",
  ui_story_5079_50791602_14_dialog_content = "Seja lá o que você acha que ouviu, esqueça isso agora mesmo!",
  ui_story_5079_50791602_15_dialog_content = "Tá bom...",
  ui_story_5079_50791602_16_dialog_content = "Mas parece que você finalmente percebeu que não precisa de mim para comandar seu poder.",
  ui_story_5079_50791602_17_dialog_content = "Então, por que se incomodar em me levar de volta? Eu sempre posso parar de seguir você se realmente quiser...",
  ui_story_5079_50791602_18_dialog_content = "Há?",
  ui_story_5079_50791602_19_dialog_content = "A única razão de as coisas terem ficado tão ruins foi porque eu te entreguei para aquele estúpido monstro de cenoura.",
  ui_story_5079_50791602_20_dialog_content = "Se um Eclipsite pegar você, quem sabe que tipo de problema ele vai causar!",
  ui_story_5079_50791602_21_dialog_content = "...",
  ui_story_5079_50791602_22_dialog_content = "Seu gosto na escolha do seu futuro mestre também é bastante horrível. Quer dizer, uma cenoura? Sério? Você não pode simplesmente escolher qualquer coisa que esteja por perto!",
  ui_story_5079_50791602_23_dialog_content = "A única pessoa digna de ser seu mestre sou eu - a grande e nobre Senhora Pact!",
  ui_story_5079_50791602_24_dialog_content = "Entender?",
  ui_story_5079_50791602_25_dialog_content = "...",
  ui_story_5079_50791602_26_dialog_content = "Você está brincando comigo, não está? Pare de fingir que não pode falar!",
  ui_story_5079_50791602_27_dialog_content = "Eu não estou, é só que... você realmente parece nobre agora...",
  ui_story_5079_50791602_28_dialog_content = "Ah...",
  ui_story_5079_50791602_29_dialog_content = "<size=30>Eu também aceito elogios como \"linda\" e \"adorável\", sabia...</size>",
  ui_story_5079_50791602_30_dialog_content = "Eu ainda não perdi!",
  ui_story_5079_50791602_31_dialog_content = "Eu... Eu vou criar... um mundo perfeito para todas as cenouras! Um onde ninguém vai me desprezar...",
  ui_story_5079_50791602_32_dialog_content = "Um mundo onde serei desejado, aceito... e autorizado a viver!",
  ui_story_5079_50791602_33_dialog_content = "Depois de tudo que aconteceu, você ainda está preso ao seu ressentimento?",
  ui_story_5079_50791602_34_dialog_content = "Vamos ter que te tirar daí—",
  ui_story_5079_50791602_35_dialog_content = "W-<size=45>Espere!</size>",
  ui_story_5079_50791602_36_dialog_content = "?",
  ui_story_5079_50791602_37_dialog_content = "Desculpe! Eu nunca deveria ter te deixado aqui ou dito todas aquelas coisas ruins...",
  ui_story_5079_50791602_38_dialog_content = "Minhas palavras te machucaram, não foi?",
  ui_story_5079_50791602_39_dialog_content = "Foi difícil, não foi? Passar todos esses dias aqui sozinho...",
  ui_story_5079_50791602_40_dialog_content = "Ninguém para conversar, ninguém precisava de você... Eu entendo como é esse sentimento...",
  ui_story_5079_50791602_41_dialog_content = "Mas se você estiver disposto a me dar outra chance...",
  ui_story_5079_50791602_42_dialog_content = "Poderíamos... Poderíamos por favor ser amigos?",
  ui_story_5079_50791602_43_dialog_content = "...",
  ui_story_5079_50791602_44_dialog_content = "Quero plantar você no canteiro mais ensolarado e fértil do nosso jardim.",
  ui_story_5079_50791602_45_dialog_content = "Quero que você absorva todos os nutrientes que precisa para crescer grande e forte e se tornar uma cenoura que qualquer um adoraria comer!",
  ui_story_5079_50791602_46_dialog_content = "Uh, Popo? Oferecer para comê-lo não é a coisa mais reconfortante a dizer... Você não preferiria que ele tivesse uma vida longa e saudável?",
  ui_story_5079_50791602_47_dialog_content = "<color=#e8d9bb>Puf!</color>",
  ui_story_5079_50791602_48_dialog_content = "Po... Popo—",
  ui_story_5079_50791602_49_dialog_content = "Isso significa... que você me perdoa?",
  ui_story_5079_50791602_50_dialog_content = "Popo!",
  ui_story_5079_50791602_51_dialog_content = "Sabe, cenouras também podem ser bem fofas...",
  ui_story_5079_50791602_52_dialog_content = "O que você acha? Devemos dar outra chance às cenouras?",
  ui_story_5079_50791602_53_dialog_content = "Uh... Acho que preciso de um pouco mais de tempo para pensar sobre isso.",
  ui_story_5079_50791602_54_dialog_content = "(Então a ideia dele de uma boa vida é ser comido por alguém de quem gosta...)",
  ui_story_5079_50791602_55_dialog_content = "(Bom, desde que seja isso que lhe dê satisfação...)",
  ui_story_5079_50791602_56_dialog_content = "... Popo?",
  ui_story_5079_50791602_57_dialog_content = "Pai? Ahh! Tente não se mover! Você está coberto de feridas...",
  ui_story_5079_50791602_58_dialog_content = "Eu mal sinto alguma coisa... Ver você vivo e bem, é tudo que eu preciso...",
  ui_story_5079_50791602_59_dialog_content = "Isso foi tudo culpa minha, Popo. Eu nunca deveria ter te dado tantas ordens... ou forçado minhas ideias em você...",
  ui_story_5079_50791602_60_dialog_content = "Eu estava muito obcecado em nos proporcionar uma vida familiar \"ideal\".",
  ui_story_5079_50791602_61_dialog_content = "E eu coloquei o peso das minhas ambições em seus ombros.",
  ui_story_5079_50791602_62_dialog_content = "Afinal, minha vida nunca valeu muito. Eu não fiz nada além de sofrer perda após perda. Eu até...",
  ui_story_5079_50791602_63_dialog_content = "Eu até perdi o amor da minha vida, sua mãe... É tudo porque eu não pude protegê-la...",
  ui_story_5079_50791602_64_dialog_content = "Pai... Todo esse tempo, você esteve escondendo sua dor pela morte da minha mãe...",
  ui_story_5079_50791602_65_dialog_content = "E desta vez, eu falhei em te proteger...",
  ui_story_5079_50791602_66_dialog_content = "Quando você fugiu de casa, eu não conseguia parar de me perguntar sobre algo - o que exatamente eu havia proporcionado para minha família?",
  ui_story_5079_50791602_67_dialog_content = "Não foi nada mais do que memórias dolorosas?",
  ui_story_5079_50791602_68_dialog_content = "Tudo que eu queria era me tornar uma família de comerciantes ricos um dia e jantar na mesma mesa que os nobres de Lumópolis.",
  ui_story_5079_50791602_69_dialog_content = "Ver você crescer e se tornar uma estrela brilhante que chama a atenção de todos, incluindo a da nobreza...",
  ui_story_5079_50791602_70_dialog_content = "Estava tão cego pelo meu sonho que nunca apreciei nossas refeições simples em nossa pequena loja ou percebi o jeito que você sorria ao comer sua comida favorita...",
  ui_story_5079_50791602_71_dialog_content = "Agarrar esses momentos é o que significa estar vivo! Ser verdadeiramente feliz!",
  ui_story_5079_50791602_72_dialog_content = "Eu...",
  ui_story_5079_50791602_73_dialog_content = "Eu... Eu quero que você também seja feliz, pai! É por isso que vou continuar dando o meu melhor!",
  ui_story_5079_50791602_74_dialog_content = "Vou te ouvir mais e parar de te causar tantos problemas! Desde que...",
  ui_story_5079_50791602_75_dialog_content = "Enquanto estivermos juntos! Estarei feliz para sempre e sempre enquanto estiver com você, pai!",
  ui_story_5079_50791602_76_dialog_content = "<size=30>Honestamente... Você não acha que deveria ir para casa antes de falar sobre todas essas coisas sentimentais?</size>",
  ui_story_5079_50791602_77_dialog_content = "<size=30>Eu quase disse algo também... Isso é tão estranho.</size>",
  ui_story_5079_50791602_78_dialog_content = "Hã? O que está no canto do meu olho?",
  ui_story_5079_50791602_79_dialog_content = "Está chovendo? Bom, isso deve lavar o cheiro das cenouras...",
  ui_story_5079_50791602_80_dialog_content = "*suspiros* Pare de chorar, seu bobo!",
  ui_story_5079_50791602_81_dialog_content = "Ah... É melhor eu não estragar minhas roupas por causa dessas lágrimas.",
  ui_story_5079_50791602_82_dialog_content = "No final—",
  ui_story_5079_50791602_83_dialog_content = "Você realizou o sonho do seu pai no final, não foi?",
  ui_story_5079_50791602_84_dialog_content = "Ah!",
  ui_story_5079_50791602_85_dialog_content = "Antes de conduzir qualquer tipo de negócio, fazer com que você pareça digno e apresentável é a coisa mais importante que você pode fazer.",
  ui_story_5079_50791602_86_dialog_content = "Apenas fazendo isso os clientes ricos lhe darão seu tempo e seu patrocínio.",
  ui_story_5079_50791602_87_dialog_content = "Você... Quando você descobriu?",
  ui_story_5079_50791602_88_dialog_content = "Quando você o chamou acidentalmente de \"pai\" mais cedo, ficou muito óbvio.",
  ui_story_5079_50791602_89_dialog_content = "Parece que você encontrou sua resposta, Pact.",
  ui_story_5079_50791602_90_dialog_content = "Não pense que você é esperto ou algo assim... Eu só falei errado, só isso...",
  ui_story_5079_50791602_91_dialog_content = "E pare de olhar para mim! Ninguém pode me ver quando estou chorando!",
  ui_story_5079_50791602_92_dialog_content = "Ei! Não vá!",
  ui_story_5079_50791602_93_dialog_content = "Huh? Uh-oh...",
  ui_story_5079_50791602_94_dialog_content = "<color=#e8d9bb>Wham—</color>",
  ui_story_5079_50791602_95_dialog_content = "...",
  ui_story_5079_50791602_96_dialog_content = "Essa é a segunda vez que você esbarra em mim assim, Popo.",
  ui_story_5079_50791602_97_dialog_content = "Eu não me importo! Você não pode ir embora ainda! Você não pode! Eu... eu ainda não agradeci direito!",
  ui_story_5079_50791602_98_dialog_content = "Eu não disse que estava saindo, eu apenas... <size=30>não queria que nenhum de vocês me visse assim.</size>",
  ui_story_5079_50791602_99_dialog_content = "Além disso, você não precisa me agradecer por nada... Eu só estava fazendo o que deveria fazer.",
  ui_story_5079_50791602_100_dialog_content = "Ah, claro! Você só não quer admitir que é uma boa pessoa! Mas agora eu sei que você é uma das pessoas mais gentis que existem!",
  ui_story_5079_50791602_101_dialog_content = "Obrigado por me ajudar a me reconciliar com meu pai, e obrigado...",
  ui_story_5079_50791602_102_dialog_content = "Por me mostrar... que sou muito amado!",
  ui_story_5079_50791602_103_dialog_content = "Eu... Eu vou fazer o meu melhor!",
  ui_story_5079_50791602_104_dialog_content = "A partir de agora, vou trabalhar duro para me tornar uma pessoa forte e gentil, assim como você!",
  ui_story_5079_50791602_105_dialog_content = "Eu? Heh... Não sou exatamente digno de ser chamado de exemplo.",
  ui_story_5079_50791602_106_dialog_content = "Apenas continue seguindo em frente e você ficará bem, Popo.",
  ui_story_5079_50791602_107_dialog_content = "Continue seguindo em frente, siga seu coração e nunca olhe para trás.",
  ui_story_5079_50791602_108_dialog_content = "Faça isso, e você encontrará todos os tipos de pessoas maravilhosas - pessoas que te respeitam, pessoas que riem com você e pessoas que te enchem de calor durante toda a sua jornada.",
  ui_story_5079_50791602_109_dialog_content = "Se você algum dia perder seu caminho, apenas levante a cabeça...",
  ui_story_5079_50791602_110_dialog_content = "Dê uma longa olhada no céu estrelado, e você encontrará as respostas que precisa, assim como eu fiz.",
  ui_story_5079_50791602_111_dialog_content = "Porque…",
  ui_story_5079_50791602_112_dialog_content = "Eu sou você, Popo.",
  ui_story_5079_50791602_113_dialog_content = "Espera... Você é o meu eu do futuro?",
  ui_story_5079_50791602_114_dialog_content = "Eu realmente espero poder ser tão incrível quanto você algum dia!",
  ui_story_5079_50791602_115_dialog_content = "Você vai, confie em mim.",
  ui_story_5079_50791602_116_dialog_content = "Ah, o pai está me dizendo para voltar pra casa agora...",
  ui_story_5079_50791602_117_dialog_content = "Não importa para onde você vá, não esqueça de mim, tá bom?",
  ui_story_5079_50791602_118_dialog_content = "Popo...",
  ui_story_5079_50791602_119_dialog_content = "Uma vez que eu me lembre de algo, nunca vou esquecer.",
  ui_story_5079_50791602_120_dialog_content = "<color=#e8d9bb>Choooo—</color>",
  ui_story_5079_50791602_121_dialog_content = "É hora de irmos.",
  ui_story_5079_50791602_122_dialog_content = "Sim, você está certo, mas eu realmente quero saber...",
  ui_story_5079_50791602_123_dialog_content = "No futuro, ela terá uma infância mais feliz do que eu aqui em Folta?",
  ui_story_5079_50791602_124_dialog_content = "Ela será capaz de sorrir por todas as vezes que eu não pude?",
  ui_story_5079_50791602_125_dialog_content = "Ela nunca terá que sentir a mesma raiva ou tristeza que eu senti?",
  ui_story_5079_50791602_126_dialog_content = "Ela... será capaz de passar a vida sem confrontar uma infância dolorosa?",
  ui_story_5079_50791602_127_dialog_content = "... Tenho certeza de que ela ficará bem. Afinal, você já curou tantos outros, incluindo a si mesmo.",
  ui_story_5079_50791602_128_dialog_content = "Lembre-se, você é a gentil e nobre Senhora Pact.",
  ui_story_5079_50791602_129_dialog_content = "Você encontrou seu caminho há muito tempo. É exatamente como você disse—",
  ui_story_5079_50791602_130_dialog_content = "\"Siga em frente, siga seu coração e nunca olhe para trás.\"",
  ui_story_5079_50791602_131_dialog_content = "O futuro de Popo está cheio de tantas possibilidades maravilhosas, e o seu também!",
  ui_story_5079_50791602_132_dialog_content = "Assim como eu pensava, você só fala quando é hora de fazer um grande discurso, e então não há quem te pare.",
  ui_story_5079_50791602_133_dialog_content = "Não fique muito sentimental. Meus problemas não são resolvidos só porque você disse algumas palavras bonitas.",
  ui_story_5079_50791602_134_dialog_content = "Agora que penso nisso, você realmente me lembra minha Pedra de Caça às vezes, PlayerName.",
  ui_story_5079_50791602_135_dialog_content = "Huh? Quando você descobriu isso?",
  ui_story_5079_50791602_136_dialog_content = "Não foi difícil. Tudo o que eu tinha que fazer era juntar sua pequena performance e seu hábito de dar discursos motivacionais.",
  ui_story_5079_50791602_137_dialog_content = "Esta é a sabedoria que ganhei das regras. Você quer que eu as explique para você?",
  ui_story_5079_50791602_138_dialog_content = "...",
  ui_story_5079_50791602_139_dialog_content = "Eu já te disse: pare de fingir que você não pode falar! Isso deixa as coisas estranhas!",
  ui_story_5079_50791602_140_dialog_content = "Eu... Eu realmente concordo com você em muitas coisas!",
  ui_story_5079_50791602_141_dialog_content = "Ainda tenho tantas palavras não ditas... e coisas por fazer!",
  ui_story_5079_50791602_142_dialog_content = "Vamos voltar ao mundo real... aquele em que realmente vivemos.",
  ui_story_5079_50791602_143_dialog_content = "Já decidi te dar uma missão... uma que só você pode completar.",
  ui_story_5079_50791602_144_dialog_content = "E antes que você pergunte, não tem como recusar... E-Então, por favor, arranje um tempo para isso!"
}
